pub fn build_call_graph_from_parser_edges(
    names: Arc<Vec<String>>,
    edges: Arc<Vec<Arc<ParserProgressEdge>>>,
) -> Arc<CallGraph> {
    Arc::new(CallGraph {
        edges: Arc::new({
            let mut __result = Vec::new();
            for edge in Arc::new({
                let mut __result = Vec::new();
                for edge in edges.clone().iter().cloned() {
                    if (edge.caller.clone() != edge.callee.clone()) {
                        __result.push(edge);
                    }
                }
                __result
            })
            .iter()
            .cloned()
            {
                __result.push(Arc::new(GraphEdge {
                    caller: edge.caller.clone(),
                    callee: edge.callee.clone(),
                }));
            }
            __result
        }),
    })
}

pub fn same_progress_subgraph_has_cycle(
    members: Arc<Vec<String>>,
    edges: Arc<Vec<Arc<ParserProgressEdge>>>,
) -> bool {
    {
        let same_edges = Arc::new({
            let mut __result = Vec::new();
            for edge in edges.clone().iter().cloned() {
                if (edge.progress.clone() == DescentEvidence::NonIncreasing) {
                    __result.push(edge);
                }
            }
            __result
        });
        let has_self_cycle = {
            let mut __found = false;
            for edge in same_edges.clone().iter().cloned() {
                if (edge.caller.clone() == edge.callee.clone()) {
                    __found = true;
                    break;
                }
            }
            __found
        };
        if has_self_cycle.clone() {
            true
        } else {
            {
                let same_cross_edges = Arc::new({
                    let mut __result = Vec::new();
                    for edge in same_edges.clone().iter().cloned() {
                        if (edge.caller.clone() != edge.callee.clone()) {
                            __result.push(edge);
                        }
                    }
                    __result
                });
                let graph =
                    build_call_graph_from_parser_edges(members.clone(), same_cross_edges.clone());
                graph_has_multi_node_scc(members.clone(), graph.clone())
            }
        }
    }
}

pub fn collect_parser_edges_for_scc(
    members: Arc<Vec<String>>,
    func_index: Arc<HashMap<String, Arc<FuncEntry>>>,
    scc_name_set: Arc<HashMap<String, bool>>,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> Arc<Vec<Arc<ParserProgressEdge>>> {
    {
        let all_have_state = {
            let mut __all = true;
            for name in members.clone().iter().cloned() {
                if !(match v1_rt::map_get(&func_index, name.clone()) {
                    Some(entry) => (parser_state_param(entry.params.clone(), si.clone()) != None),
                    None => false,
                }) {
                    __all = false;
                    break;
                }
            }
            __all
        };
        if (all_have_state.clone() == false) {
            Arc::new(vec![])
        } else {
            {
                let proven = infer_parser_always_advancing_members(
                    parser_function_names(func_index.clone(), si.clone()),
                    func_index.clone(),
                    si.clone(),
                );
                let parser_always_advancing = proven.clone();
                Arc::new({
                    let mut __result = Vec::new();
                    for name in members.clone().iter().cloned() {
                        __result.extend(
                            (*match v1_rt::map_get(&func_index, name.clone()) {
                                Some(entry) => {
                                    match parser_state_param(entry.params.clone(), si.clone()) {
                                        Some(state_param) => collect_parser_progress_edges(
                                            name.clone(),
                                            entry.body.clone(),
                                            state_param.clone(),
                                            scc_name_set.clone(),
                                            empty_parser_progress_env(),
                                            parser_always_advancing.clone(),
                                            v1_rt::rc_empty_map::<String, bool>(),
                                            si.clone(),
                                        ),
                                        None => Arc::new(vec![]),
                                    }
                                }
                                None => Arc::new(vec![]),
                            })
                            .iter()
                            .cloned(),
                        );
                    }
                    __result
                })
            }
        }
    }
}

pub fn classify_parser_scc_recursion_pattern(
    members: Arc<Vec<String>>,
    func_index: Arc<HashMap<String, Arc<FuncEntry>>>,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> Option<Arc<LoweringTarget>> {
    {
        let scc_name_set = members.clone().iter().cloned().fold(
            v1_rt::rc_empty_map::<String, bool>(),
            |acc: Arc<HashMap<String, bool>>, name: String| {
                v1_rt::rc_map_insert(acc, name.clone(), true)
            },
        );
        let edges = collect_parser_edges_for_scc(
            members.clone(),
            func_index.clone(),
            scc_name_set.clone(),
            si.clone(),
        );
        if ((edges.clone().len() as i64) == 0) {
            None
        } else {
            {
                let all_known = {
                    let mut __all = true;
                    for edge in edges.clone().iter().cloned() {
                        if !(edge.progress.clone() != DescentEvidence::DescentUnknown) {
                            __all = false;
                            break;
                        }
                    }
                    __all
                };
                if (all_known.clone()
                    && (same_progress_subgraph_has_cycle(members.clone(), edges.clone()) == false))
                {
                    Some(lower_call_pattern(Arc::new(
                        CallPattern::ParserAdvanceCall {
                            witness: "parser_state".to_string(),
                        },
                    )))
                } else {
                    None
                }
            }
        }
    }
}

pub fn count_self_calls(
    body: Arc<Node>,
    func_name: String,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> i64 {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        let own = match (*body.expr_data.clone()).clone() {
            ExprData::ExprCall { .. } => {
                let f = expr_call_func_at(body.clone(), si.clone());
                if (f.clone() == func_name.clone()) {
                    1
                } else {
                    0
                }
            }
            _ => 0,
        };
        let from_children =
            body.children
                .clone()
                .iter()
                .cloned()
                .fold(0, |acc: i64, child: Arc<Node>| {
                    (acc + count_self_calls(child.clone(), func_name.clone(), si.clone()))
                });
        (own.clone() + from_children.clone())
    })
}

pub fn max_path_self_calls(
    body: Arc<Node>,
    func_name: String,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> i64 {
    max_path_self_calls_with_cont(body.clone(), func_name.clone(), 0, si.clone())
}

pub fn max_path_self_calls_with_cont(
    body: Arc<Node>,
    func_name: String,
    continue_calls: i64,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> i64 {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*body.expr_data.clone()).clone() {
            ExprData::ExprCall { .. } => {
                let f = expr_call_func_at(body.clone(), si.clone());
                let own = if (f.clone() == func_name.clone()) {
                    1
                } else {
                    0
                };
                let arg_calls =
                    body.children
                        .clone()
                        .iter()
                        .cloned()
                        .fold(0, |acc: i64, child: Arc<Node>| {
                            let val = arg_value(child.clone());
                            match (*val.expr_data.clone()).clone() {
                                ExprData::ExprLambda => {
                                    (acc.clone()
                                        + max_path_self_calls_with_cont(
                                            lambda_body(val.clone()),
                                            func_name.clone(),
                                            0,
                                            si.clone(),
                                        ))
                                }
                                _ => {
                                    (acc.clone()
                                        + max_path_self_calls_with_cont(
                                            val.clone(),
                                            func_name.clone(),
                                            0,
                                            si.clone(),
                                        ))
                                }
                            }
                        });
                ((own.clone() + arg_calls.clone()) + continue_calls.clone())
            }
            ExprData::ExprMatch => {
                let scrut_calls = max_path_self_calls_with_cont(
                    match_scrutinee(body.clone()),
                    func_name.clone(),
                    0,
                    si.clone(),
                );
                let max_arm = match_arm_nodes(body.clone()).iter().cloned().fold(
                    continue_calls.clone(),
                    |acc: i64, arm_node: Arc<Node>| {
                        let arm_calls = max_path_self_calls_with_cont(
                            arm_body(arm_node.clone()),
                            func_name.clone(),
                            continue_calls.clone(),
                            si.clone(),
                        );
                        if (arm_calls.clone() > acc.clone()) {
                            arm_calls.clone()
                        } else {
                            acc.clone()
                        }
                    },
                );
                (scrut_calls.clone() + max_arm.clone())
            }
            ExprData::ExprIf => {
                let cond_calls = max_path_self_calls_with_cont(
                    if_condition(body.clone()),
                    func_name.clone(),
                    0,
                    si.clone(),
                );
                let then_calls = max_path_self_calls_with_cont(
                    if_then_branch(body.clone()),
                    func_name.clone(),
                    continue_calls.clone(),
                    si.clone(),
                );
                let else_calls = match if_else_branch(body.clone()) {
                    Some(eb) => max_path_self_calls_with_cont(
                        eb.clone(),
                        func_name.clone(),
                        continue_calls.clone(),
                        si.clone(),
                    ),
                    None => continue_calls.clone(),
                };
                let branch_max = if (then_calls.clone() > else_calls.clone()) {
                    then_calls.clone()
                } else {
                    else_calls.clone()
                };
                (cond_calls.clone() + branch_max.clone())
            }
            ExprData::ExprForEach => {
                (max_path_self_calls_with_cont(
                    foreach_collection(body.clone()),
                    func_name.clone(),
                    0,
                    si.clone(),
                ) + continue_calls.clone())
            }
            ExprData::ExprLet => {
                let val_calls = max_path_self_calls_with_cont(
                    let_value(body.clone()),
                    func_name.clone(),
                    0,
                    si.clone(),
                );
                let body_calls = match let_body(body.clone()) {
                    Some(b) => max_path_self_calls_with_cont(
                        b.clone(),
                        func_name.clone(),
                        continue_calls.clone(),
                        si.clone(),
                    ),
                    None => continue_calls.clone(),
                };
                (val_calls.clone() + body_calls.clone())
            }
            ExprData::ExprBlock => v1_rt::reverse(body.children.clone()).iter().cloned().fold(
                continue_calls.clone(),
                |acc: i64, stmt: Arc<Node>| {
                    max_path_self_calls_with_cont(stmt.clone(), func_name.clone(), acc, si.clone())
                },
            ),
            ExprData::ExprMethodCall {
                method_semantics: _,
                ..
            } => {
                let recv_calls = max_path_self_calls_with_cont(
                    method_receiver(body.clone()),
                    func_name.clone(),
                    0,
                    si.clone(),
                );
                let arg_calls = method_arg_nodes(body.clone()).iter().cloned().fold(
                    0,
                    |acc: i64, arg_node: Arc<Node>| {
                        let val = arg_value(arg_node.clone());
                        match (*val.expr_data.clone()).clone() {
                            ExprData::ExprLambda => {
                                (acc.clone()
                                    + max_path_self_calls_with_cont(
                                        lambda_body(val.clone()),
                                        func_name.clone(),
                                        0,
                                        si.clone(),
                                    ))
                            }
                            _ => {
                                (acc.clone()
                                    + max_path_self_calls_with_cont(
                                        val.clone(),
                                        func_name.clone(),
                                        0,
                                        si.clone(),
                                    ))
                            }
                        }
                    },
                );
                ((recv_calls.clone() + arg_calls.clone()) + continue_calls.clone())
            }
            ExprData::ExprReturn => max_path_self_calls_with_cont(
                return_value(body.clone()),
                func_name.clone(),
                0,
                si.clone(),
            ),
            _ => {
                (body
                    .children
                    .clone()
                    .iter()
                    .cloned()
                    .fold(0, |acc: i64, child: Arc<Node>| {
                        (acc + max_path_self_calls_with_cont(
                            child.clone(),
                            func_name.clone(),
                            0,
                            si.clone(),
                        ))
                    })
                    + continue_calls.clone())
            }
        }
    })
}

pub fn max_path_self_calls_block(
    stmts: Arc<Vec<Arc<Node>>>,
    func_name: String,
    continue_calls: i64,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> i64 {
    v1_rt::reverse(stmts.clone()).iter().cloned().fold(
        continue_calls.clone(),
        |acc: i64, stmt: Arc<Node>| {
            max_path_self_calls_with_cont(stmt.clone(), func_name.clone(), acc, si.clone())
        },
    )
}

