pub fn recursive_measure_param_names(
    body: Arc<Node>,
    params: Arc<Vec<Arc<Node>>>,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> Arc<HashMap<String, String>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        let param_set = params.clone().iter().cloned().fold(
            v1_rt::rc_empty_map::<String, String>(),
            |acc: Arc<HashMap<String, String>>, param: Arc<Node>| {
                v1_rt::rc_map_insert(
                    acc,
                    param_node_name_at(param.clone(), si.clone()),
                    param_node_name_at(param.clone(), si.clone()),
                )
            },
        );
        match (*body.expr_data.clone()).clone() {
            ExprData::ExprIf => {
                let then_names = recursive_measure_param_names(
                    if_then_branch(body.clone()),
                    params.clone(),
                    si.clone(),
                );
                let else_names = match if_else_branch(body.clone()) {
                    Some(eb) => {
                        recursive_measure_param_names(eb.clone(), params.clone(), si.clone())
                    }
                    None => v1_rt::rc_empty_map::<String, String>(),
                };
                v1_rt::rc_map_merge(
                    v1_rt::rc_map_merge(
                        condition_param_names(
                            if_condition(body.clone()),
                            param_set.clone(),
                            si.clone(),
                        ),
                        then_names.clone(),
                    ),
                    else_names.clone(),
                )
            }
            ExprData::ExprMatch => {
                let scrut_names = condition_param_names(
                    match_scrutinee(body.clone()),
                    param_set.clone(),
                    si.clone(),
                );
                let arm_names = match_arm_nodes(body.clone()).iter().cloned().fold(
                    v1_rt::rc_empty_map::<String, String>(),
                    |acc: Arc<HashMap<String, String>>, arm_node: Arc<Node>| {
                        v1_rt::rc_map_merge(
                            acc,
                            recursive_measure_param_names(
                                arm_body(arm_node.clone()),
                                params.clone(),
                                si.clone(),
                            ),
                        )
                    },
                );
                v1_rt::rc_map_merge(scrut_names.clone(), arm_names.clone())
            }
            ExprData::ExprLet => match let_body(body.clone()) {
                Some(b) => recursive_measure_param_names(b.clone(), params.clone(), si.clone()),
                None => v1_rt::rc_empty_map::<String, String>(),
            },
            ExprData::ExprBlock => body.children.clone().iter().cloned().fold(
                v1_rt::rc_empty_map::<String, String>(),
                |acc: Arc<HashMap<String, String>>, stmt: Arc<Node>| {
                    v1_rt::rc_map_merge(
                        acc,
                        recursive_measure_param_names(stmt.clone(), params.clone(), si.clone()),
                    )
                },
            ),
            _ => body.children.clone().iter().cloned().fold(
                v1_rt::rc_empty_map::<String, String>(),
                |acc: Arc<HashMap<String, String>>, child: Arc<Node>| {
                    v1_rt::rc_map_merge(
                        acc,
                        recursive_measure_param_names(child.clone(), params.clone(), si.clone()),
                    )
                },
            ),
        }
    })
}

pub fn recursive_param_name_for_arg(
    idx: i64,
    arg_node: Arc<Node>,
    params: Arc<Vec<Arc<Node>>>,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> Option<String> {
    match arg_name_at(arg_node.clone(), si.clone()) {
        Some(name) => Some(name.clone()),
        None => Arc::new({
            let mut __result = Vec::new();
            for pair in Arc::new({
                let mut __result = Vec::new();
                for pair in Arc::new(
                    params
                        .clone()
                        .iter()
                        .cloned()
                        .enumerate()
                        .map(|(i, v)| (i as i64, v))
                        .collect::<Vec<_>>(),
                )
                .iter()
                .cloned()
                {
                    if (pair.0.clone() == idx.clone()) {
                        __result.push(pair);
                    }
                }
                __result
            })
            .iter()
            .cloned()
            {
                __result.push(param_node_name_at(pair.1.clone(), si.clone()));
            }
            __result
        })
        .first()
        .cloned(),
    }
}

