pub fn is_tokens_input_expr(
    mut expr: Arc<Node>,
    mut param_name: String,
    mut vars: Arc<HashMap<String, bool>>,
    mut si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> bool {
    loop {
        match (*expr.expr_data.clone()).clone() {
            ExprData::ExprVar {
                binding_kind: _, ..
            } => {
                let vname = expr_var_name_at(expr.clone(), si.clone());
                break ((vname.clone() == param_name.clone())
                    || set_has(vars.clone(), vname.clone()));
            }
            ExprData::ExprFieldAccess { .. } => {
                let field = field_access_field_at(expr.clone(), si.clone());
                if (field.clone() == param_name.clone()) {
                    break true;
                } else {
                    let base = field_access_base(expr.clone());
                    match (*base.expr_data.clone()).clone() {
                        ExprData::ExprVar {
                            binding_kind: _, ..
                        } => {
                            let bname = expr_var_name_at(base.clone(), si.clone());
                            break ((bname.clone() == param_name.clone())
                                || set_has(vars.clone(), bname.clone()));
                        }
                        _ => {
                            break false;
                        }
                    }
                }
            }
            ExprData::ExprMethodCall {
                method_semantics: ms,
                ..
            } => match method_size_effect(ms.clone()) {
                Some(CollectionSizeEffect::ShrinkEffect) => {
                    let __tco_0 = method_receiver(expr);
                    expr = __tco_0;
                    continue;
                }
                _ => {
                    break false;
                }
            },
            ExprData::ExprCall { .. } => {
                if is_list_passthrough_call(expr.clone(), si.clone()) {
                    match list_passthrough_inner_arg(expr.clone(), si.clone()) {
                        Some(inner) => {
                            let __tco_0 = inner.clone();
                            expr = __tco_0;
                            continue;
                        }
                        None => {
                            break false;
                        }
                    }
                } else {
                    match consuming_tokens_arg(expr.clone(), si.clone()) {
                        Some(tokens_arg) => {
                            let __tco_0 = tokens_arg.clone();
                            expr = __tco_0;
                            continue;
                        }
                        None => {
                            break false;
                        }
                    }
                }
            }
            _ => {
                break false;
            }
        }
    }
}

pub fn is_descent_arg(
    expr: Arc<Node>,
    param_name: String,
    descent_vars: Arc<HashMap<String, bool>>,
    check_child: bool,
    check_list: bool,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> bool {
    match (*expr.expr_data.clone()).clone() {
        ExprData::ExprVar {
            binding_kind: _, ..
        } => {
            let vname = expr_var_name_at(expr.clone(), si.clone());
            set_has(descent_vars.clone(), vname.clone())
        }
        _ => {
            ((check_child.clone()
                && is_child_descent_expr(
                    expr.clone(),
                    param_name.clone(),
                    descent_vars.clone(),
                    si.clone(),
                ))
                || (check_list.clone()
                    && is_list_shrink_expr(expr.clone(), param_name.clone(), si.clone())))
        }
    }
}

pub fn expr_contains_descent(
    expr: Arc<Node>,
    param_name: String,
    vars: Arc<HashMap<String, bool>>,
    check_child: bool,
    check_list: bool,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> bool {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        if ((check_child.clone()
            && is_child_descent_expr(expr.clone(), param_name.clone(), vars.clone(), si.clone()))
            || (check_list.clone()
                && is_list_shrink_expr(expr.clone(), param_name.clone(), si.clone())))
        {
            true
        } else {
            match (*expr.expr_data.clone()).clone() {
                ExprData::ExprIf => {
                    (expr_contains_descent(
                        if_then_branch(expr.clone()),
                        param_name.clone(),
                        vars.clone(),
                        check_child.clone(),
                        check_list.clone(),
                        si.clone(),
                    ) && match if_else_branch(expr.clone()) {
                        Some(eb) => expr_contains_descent(
                            eb.clone(),
                            param_name.clone(),
                            vars.clone(),
                            check_child.clone(),
                            check_list.clone(),
                            si.clone(),
                        ),
                        None => false,
                    })
                }
                ExprData::ExprBlock => match expr.children.clone().last().cloned() {
                    Some(last_stmt) => expr_contains_descent(
                        last_stmt.clone(),
                        param_name.clone(),
                        vars.clone(),
                        check_child.clone(),
                        check_list.clone(),
                        si.clone(),
                    ),
                    None => false,
                },
                ExprData::ExprVar {
                    binding_kind: _, ..
                } => set_has(vars.clone(), expr_var_name_at(expr.clone(), si.clone())),
                ExprData::ExprFieldAccess { .. } => {
                    let field = field_access_field_at(expr.clone(), si.clone());
                    let base = field_access_base(expr.clone());
                    (is_sub_value_field(field.clone())
                        && match (*base.expr_data.clone()).clone() {
                            ExprData::ExprVar {
                                binding_kind: _, ..
                            } => {
                                let bname = expr_var_name_at(base.clone(), si.clone());
                                ((bname.clone() == param_name.clone())
                                    || set_has(vars.clone(), bname.clone()))
                            }
                            _ => false,
                        })
                }
                ExprData::ExprMethodCall {
                    method_semantics: ms,
                    ..
                } => {
                    let receiver = method_receiver(expr.clone());
                    match method_size_effect(ms.clone()) {
                        Some(CollectionSizeEffect::ShrinkEffect) => expr_contains_descent(
                            receiver.clone(),
                            param_name.clone(),
                            vars.clone(),
                            check_child.clone(),
                            check_list.clone(),
                            si.clone(),
                        ),
                        Some(CollectionSizeEffect::ProjectionEffect) => expr_contains_descent(
                            receiver.clone(),
                            param_name.clone(),
                            vars.clone(),
                            check_child.clone(),
                            check_list.clone(),
                            si.clone(),
                        ),
                        Some(CollectionSizeEffect::IdentityEffect) => expr_contains_descent(
                            receiver.clone(),
                            param_name.clone(),
                            vars.clone(),
                            check_child.clone(),
                            check_list.clone(),
                            si.clone(),
                        ),
                        None => false,
                    }
                }
                _ => false,
            }
        }
    })
}

pub fn collect_field_binding_names(
    fb: Arc<Node>,
    vars: Arc<HashMap<String, bool>>,
) -> Arc<HashMap<String, bool>> {
    stacker::maybe_grow(
        512 * 1024,
        2 * 1024 * 1024,
        || match (*field_binding_pattern(fb.clone())).clone() {
            MatchPattern::Bind {
                name: binding_name, ..
            } => v1_rt::rc_map_insert(vars.clone(), binding_name.clone(), true),
            MatchPattern::VariantPattern {
                field_bindings: nested,
                ..
            } => nested.clone().iter().cloned().fold(
                vars.clone(),
                |inner: Arc<HashMap<String, bool>>, nested_fb: Arc<Node>| {
                    collect_field_binding_names(nested_fb.clone(), inner)
                },
            ),
            _ => vars.clone(),
        },
    )
}

pub fn is_if_option_descent(
    val: Arc<Node>,
    param_name: String,
    vars: Arc<HashMap<String, bool>>,
    check_child: bool,
    check_list: bool,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> bool {
    match (*val.expr_data.clone()).clone() {
        ExprData::ExprIf => {
            let then_branch = if_then_branch(val.clone());
            let then_has_descent = expr_contains_descent(
                then_branch.clone(),
                param_name.clone(),
                vars.clone(),
                check_child.clone(),
                check_list.clone(),
                si.clone(),
            );
            let else_is_none = match if_else_branch(val.clone()) {
                Some(eb) => match (*eb.expr_data.clone()).clone() {
                    ExprData::ExprVar {
                        binding_kind: _, ..
                    } => (expr_var_name_at(eb.clone(), si.clone()) == "none".to_string()),
                    ExprData::ExprLiteral { value: v, .. } => match (*v.clone()).clone() {
                        LiteralValue::LitNull => true,
                        _ => false,
                    },
                    _ => false,
                },
                None => true,
            };
            (then_has_descent.clone() && else_is_none.clone())
        }
        _ => false,
    }
}

pub fn is_match_option_descent(
    val: Arc<Node>,
    param_name: String,
    vars: Arc<HashMap<String, bool>>,
    check_child: bool,
    check_list: bool,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> bool {
    match (*val.expr_data.clone()).clone() {
        ExprData::ExprMatch => {
            let scrut = match_scrutinee(val.clone());
            let scrut_has_descent = expr_contains_descent(
                scrut.clone(),
                param_name.clone(),
                vars.clone(),
                check_child.clone(),
                check_list.clone(),
                si.clone(),
            );
            if scrut_has_descent.clone() {
                {
                    let has_extraction = {
                        let mut __found = false;
                        for arm_node in match_arm_nodes(val.clone()).iter().cloned() {
                            if match (*arm_pattern(arm_node.clone())).clone() {
                                MatchPattern::VariantPattern {
                                    field_bindings: bindings,
                                    ..
                                } => {
                                    let binding_names = bindings.clone().iter().cloned().fold(
                                        v1_rt::rc_empty_map::<String, bool>(),
                                        |acc: Arc<HashMap<String, bool>>, fb: Arc<Node>| {
                                            collect_field_binding_names(fb.clone(), acc)
                                        },
                                    );
                                    let arm_b = arm_body(arm_node.clone());
                                    match (*arm_b.expr_data.clone()).clone() {
                                        ExprData::ExprVar {
                                            binding_kind: _, ..
                                        } => set_has(
                                            binding_names.clone(),
                                            expr_var_name_at(arm_b.clone(), si.clone()),
                                        ),
                                        _ => false,
                                    }
                                }
                                _ => false,
                            } {
                                __found = true;
                                break;
                            }
                        }
                        __found
                    };
                    let all_safe = {
                        let mut __all = true;
                        for arm_node in match_arm_nodes(val.clone()).iter().cloned() {
                            if !({
                                let arm_b = arm_body(arm_node.clone());
                                match (*arm_b.expr_data.clone()).clone() {
                                    ExprData::ExprVar {
                                        binding_kind: _, ..
                                    } => {
                                        (expr_var_name_at(arm_b.clone(), si.clone())
                                            != param_name.clone())
                                    }
                                    _ => true,
                                }
                            }) {
                                __all = false;
                                break;
                            }
                        }
                        __all
                    };
                    (has_extraction.clone() && all_safe.clone())
                }
            } else {
                false
            }
        }
        _ => false,
    }
}

pub fn collect_descent_vars(
    body: Arc<Node>,
    param_name: String,
    vars: Arc<HashMap<String, bool>>,
    check_child: bool,
    check_list: bool,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> Arc<HashMap<String, bool>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*body.expr_data.clone()).clone() {
            ExprData::ExprLet => {
                let val = let_value(body.clone());
                let is_direct_descent = ((check_child.clone()
                    && is_child_descent_expr(
                        val.clone(),
                        param_name.clone(),
                        vars.clone(),
                        si.clone(),
                    ))
                    || (check_list.clone()
                        && is_list_shrink_expr(val.clone(), param_name.clone(), si.clone())));
                let is_descent_var = match (*val.expr_data.clone()).clone() {
                    ExprData::ExprVar {
                        binding_kind: _, ..
                    } => set_has(vars.clone(), expr_var_name_at(val.clone(), si.clone())),
                    _ => false,
                };
                let is_option_descent = is_if_option_descent(
                    val.clone(),
                    param_name.clone(),
                    vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    si.clone(),
                );
                let is_match_descent = is_match_option_descent(
                    val.clone(),
                    param_name.clone(),
                    vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    si.clone(),
                );
                let is_wrapped_descent = if is_tree_size_preserving_wrapper(val.clone(), si.clone())
                {
                    {
                        let inner = wrapper_inner_arg(val.clone());
                        let inner_is_descent = ((check_child.clone()
                            && is_child_descent_expr(
                                inner.clone(),
                                param_name.clone(),
                                vars.clone(),
                                si.clone(),
                            ))
                            || (check_list.clone()
                                && is_list_shrink_expr(
                                    inner.clone(),
                                    param_name.clone(),
                                    si.clone(),
                                )));
                        let inner_is_var = match (*inner.expr_data.clone()).clone() {
                            ExprData::ExprVar {
                                binding_kind: _, ..
                            } => set_has(vars.clone(), expr_var_name_at(inner.clone(), si.clone())),
                            _ => false,
                        };
                        (inner_is_descent.clone() || inner_is_var.clone())
                    }
                } else {
                    false
                };
                let is_extraction_descent = if is_sub_value_extractor(val.clone(), si.clone()) {
                    {
                        let inner = extractor_inner_arg(val.clone());
                        let inner_is_descent = ((check_child.clone()
                            && is_child_descent_expr(
                                inner.clone(),
                                param_name.clone(),
                                vars.clone(),
                                si.clone(),
                            ))
                            || (check_list.clone()
                                && is_list_shrink_expr(
                                    inner.clone(),
                                    param_name.clone(),
                                    si.clone(),
                                )));
                        let inner_is_var = match (*inner.expr_data.clone()).clone() {
                            ExprData::ExprVar {
                                binding_kind: _, ..
                            } => set_has(vars.clone(), expr_var_name_at(inner.clone(), si.clone())),
                            _ => false,
                        };
                        let inner_is_param = match (*inner.expr_data.clone()).clone() {
                            ExprData::ExprVar {
                                binding_kind: _, ..
                            } => {
                                (expr_var_name_at(inner.clone(), si.clone()) == param_name.clone())
                            }
                            _ => false,
                        };
                        ((inner_is_descent.clone() || inner_is_var.clone())
                            || inner_is_param.clone())
                    }
                } else {
                    false
                };
                let is_children_list = match (*val.expr_data.clone()).clone() {
                    ExprData::ExprFieldAccess { .. } => {
                        let base = field_access_base(val.clone());
                        let field = field_access_field_at(val.clone(), si.clone());
                        (is_children_list_field(field.clone())
                            && match (*base.expr_data.clone()).clone() {
                                ExprData::ExprVar {
                                    binding_kind: _, ..
                                } => {
                                    let bname = expr_var_name_at(base.clone(), si.clone());
                                    ((bname.clone() == param_name.clone())
                                        || set_has(vars.clone(), bname.clone()))
                                }
                                _ => false,
                            })
                    }
                    _ => false,
                };
                let is_passthrough_descent = if is_list_passthrough_call(val.clone(), si.clone()) {
                    match list_passthrough_inner_arg(val.clone(), si.clone()) {
                        Some(inner) => {
                            (((check_child.clone()
                                && is_child_descent_expr(
                                    inner.clone(),
                                    param_name.clone(),
                                    vars.clone(),
                                    si.clone(),
                                ))
                                || (check_list.clone()
                                    && is_list_shrink_expr(
                                        inner.clone(),
                                        param_name.clone(),
                                        si.clone(),
                                    )))
                                || match (*inner.expr_data.clone()).clone() {
                                    ExprData::ExprVar {
                                        binding_kind: _, ..
                                    } => set_has(
                                        vars.clone(),
                                        expr_var_name_at(inner.clone(), si.clone()),
                                    ),
                                    _ => false,
                                })
                        }
                        None => false,
                    }
                } else {
                    false
                };
                let is_consuming_helper = (check_list.clone()
                    && is_tokens_consuming_call(
                        val.clone(),
                        param_name.clone(),
                        vars.clone(),
                        si.clone(),
                    ));
                let val_is_descent = ((((((((is_direct_descent.clone()
                    || is_descent_var.clone())
                    || is_option_descent.clone())
                    || is_match_descent.clone())
                    || is_wrapped_descent.clone())
                    || is_extraction_descent.clone())
                    || is_children_list.clone())
                    || is_passthrough_descent.clone())
                    || is_consuming_helper.clone());
                let next_vars = if val_is_descent.clone() {
                    v1_rt::rc_map_insert(
                        vars.clone(),
                        let_binding_name_at(body.clone(), si.clone()),
                        true,
                    )
                } else {
                    vars.clone()
                };
                match let_body(body.clone()) {
                    Some(b) => collect_descent_vars(
                        b.clone(),
                        param_name.clone(),
                        next_vars.clone(),
                        check_child.clone(),
                        check_list.clone(),
                        si.clone(),
                    ),
                    None => next_vars.clone(),
                }
            }
            ExprData::ExprMatch => {
                let scrut = match_scrutinee(body.clone());
                let scrut_is_descent = expr_contains_descent(
                    scrut.clone(),
                    param_name.clone(),
                    vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    si.clone(),
                );
                let scrut_is_param = match (*scrut.expr_data.clone()).clone() {
                    ExprData::ExprVar {
                        binding_kind: _, ..
                    } => {
                        let sname = expr_var_name_at(scrut.clone(), si.clone());
                        ((sname.clone() == param_name.clone())
                            || set_has(vars.clone(), sname.clone()))
                    }
                    _ => false,
                };
                let with_patterns = if (scrut_is_descent.clone() || scrut_is_param.clone()) {
                    match_arm_nodes(body.clone()).iter().cloned().fold(
                        vars.clone(),
                        |acc: Arc<HashMap<String, bool>>, arm_node: Arc<Node>| match (*arm_pattern(
                            arm_node.clone(),
                        ))
                        .clone()
                        {
                            MatchPattern::VariantPattern {
                                field_bindings: bindings,
                                ..
                            } => bindings.clone().iter().cloned().fold(
                                acc.clone(),
                                |inner: Arc<HashMap<String, bool>>, fb: Arc<Node>| {
                                    collect_field_binding_names(fb.clone(), inner)
                                },
                            ),
                            MatchPattern::Bind {
                                name: binding_name, ..
                            } => {
                                if scrut_is_descent.clone() {
                                    v1_rt::rc_map_insert(acc.clone(), binding_name.clone(), true)
                                } else {
                                    acc.clone()
                                }
                            }
                            _ => acc.clone(),
                        },
                    )
                } else {
                    vars.clone()
                };
                match_arm_nodes(body.clone()).iter().cloned().fold(
                    with_patterns.clone(),
                    |acc: Arc<HashMap<String, bool>>, arm_node: Arc<Node>| {
                        let arm_result = collect_descent_vars(
                            arm_body(arm_node.clone()),
                            param_name.clone(),
                            with_patterns.clone(),
                            check_child.clone(),
                            check_list.clone(),
                            si.clone(),
                        );
                        v1_rt::rc_map_merge(acc, arm_result.clone())
                    },
                )
            }
            ExprData::ExprIf => {
                let then_vars = collect_descent_vars(
                    if_then_branch(body.clone()),
                    param_name.clone(),
                    vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    si.clone(),
                );
                let else_vars = match if_else_branch(body.clone()) {
                    Some(eb) => collect_descent_vars(
                        eb.clone(),
                        param_name.clone(),
                        vars.clone(),
                        check_child.clone(),
                        check_list.clone(),
                        si.clone(),
                    ),
                    None => vars.clone(),
                };
                v1_rt::rc_map_merge(then_vars.clone(), else_vars.clone())
            }
            ExprData::ExprBlock => body.children.clone().iter().cloned().fold(
                vars.clone(),
                |acc: Arc<HashMap<String, bool>>, stmt: Arc<Node>| {
                    collect_descent_vars(
                        stmt.clone(),
                        param_name.clone(),
                        acc,
                        check_child.clone(),
                        check_list.clone(),
                        si.clone(),
                    )
                },
            ),
            ExprData::ExprReturn => match body.children.clone().first().cloned() {
                Some(inner) => collect_descent_vars(
                    inner.clone(),
                    param_name.clone(),
                    vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    si.clone(),
                ),
                None => vars.clone(),
            },
            _ => vars.clone(),
        }
    })
}

pub fn all_self_calls_descend(
    body: Arc<Node>,
    func_name: String,
    param_name: String,
    check_child: bool,
    check_list: bool,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> bool {
    all_self_calls_descend_inc(
        body.clone(),
        func_name.clone(),
        param_name.clone(),
        v1_rt::rc_empty_map::<String, bool>(),
        check_child.clone(),
        check_list.clone(),
        si.clone(),
    )
}

pub fn all_self_calls_descend_inc(
    body: Arc<Node>,
    func_name: String,
    param_name: String,
    vars: Arc<HashMap<String, bool>>,
    check_child: bool,
    check_list: bool,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> bool {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*body.expr_data.clone()).clone() {
            ExprData::ExprLambda => true,
            ExprData::ExprLet => {
                let val = let_value(body.clone());
                let val_ok = all_self_calls_descend_inc(
                    val.clone(),
                    func_name.clone(),
                    param_name.clone(),
                    vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    si.clone(),
                );
                let is_direct = ((check_child.clone()
                    && is_child_descent_expr(
                        val.clone(),
                        param_name.clone(),
                        vars.clone(),
                        si.clone(),
                    ))
                    || (check_list.clone()
                        && is_list_shrink_expr(val.clone(), param_name.clone(), si.clone())));
                let is_var = match (*val.expr_data.clone()).clone() {
                    ExprData::ExprVar {
                        binding_kind: _, ..
                    } => set_has(vars.clone(), expr_var_name_at(val.clone(), si.clone())),
                    _ => false,
                };
                let is_option = is_if_option_descent(
                    val.clone(),
                    param_name.clone(),
                    vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    si.clone(),
                );
                let is_children_list = match (*val.expr_data.clone()).clone() {
                    ExprData::ExprFieldAccess { .. } => {
                        let base = field_access_base(val.clone());
                        let field = field_access_field_at(val.clone(), si.clone());
                        (is_children_list_field(field.clone())
                            && match (*base.expr_data.clone()).clone() {
                                ExprData::ExprVar {
                                    binding_kind: _, ..
                                } => {
                                    let bname = expr_var_name_at(base.clone(), si.clone());
                                    ((bname.clone() == param_name.clone())
                                        || set_has(vars.clone(), bname.clone()))
                                }
                                _ => false,
                            })
                    }
                    _ => false,
                };
                let next_vars = if (((is_direct.clone() || is_var.clone()) || is_option.clone())
                    || is_children_list.clone())
                {
                    v1_rt::rc_map_insert(
                        vars.clone(),
                        let_binding_name_at(body.clone(), si.clone()),
                        true,
                    )
                } else {
                    vars.clone()
                };
                let body_ok = match let_body(body.clone()) {
                    Some(b) => all_self_calls_descend_inc(
                        b.clone(),
                        func_name.clone(),
                        param_name.clone(),
                        next_vars.clone(),
                        check_child.clone(),
                        check_list.clone(),
                        si.clone(),
                    ),
                    None => true,
                };
                (val_ok.clone() && body_ok.clone())
            }
            ExprData::ExprMatch => {
                let scrut = match_scrutinee(body.clone());
                let scrut_ok = all_self_calls_descend_inc(
                    scrut.clone(),
                    func_name.clone(),
                    param_name.clone(),
                    vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    si.clone(),
                );
                let scrut_is_descent = expr_contains_descent(
                    scrut.clone(),
                    param_name.clone(),
                    vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    si.clone(),
                );
                let scrut_is_param = match (*scrut.expr_data.clone()).clone() {
                    ExprData::ExprVar {
                        binding_kind: _, ..
                    } => {
                        let sname = expr_var_name_at(scrut.clone(), si.clone());
                        ((sname.clone() == param_name.clone())
                            || set_has(vars.clone(), sname.clone()))
                    }
                    _ => false,
                };
                let arms_ok = {
                    let mut __all = true;
                    for arm_node in match_arm_nodes(body.clone()).iter().cloned() {
                        if !({
                            let arm_vars = if (scrut_is_descent.clone() || scrut_is_param.clone()) {
                                match (*arm_pattern(arm_node.clone())).clone() {
                                    MatchPattern::VariantPattern {
                                        field_bindings: bindings,
                                        ..
                                    } => bindings.clone().iter().cloned().fold(
                                        vars.clone(),
                                        |inner: Arc<HashMap<String, bool>>, fb: Arc<Node>| {
                                            collect_field_binding_names(fb.clone(), inner)
                                        },
                                    ),
                                    MatchPattern::Bind {
                                        name: binding_name, ..
                                    } => {
                                        if scrut_is_descent.clone() {
                                            v1_rt::rc_map_insert(
                                                vars.clone(),
                                                binding_name.clone(),
                                                true,
                                            )
                                        } else {
                                            vars.clone()
                                        }
                                    }
                                    _ => vars.clone(),
                                }
                            } else {
                                vars.clone()
                            };
                            all_self_calls_descend_inc(
                                arm_body(arm_node.clone()),
                                func_name.clone(),
                                param_name.clone(),
                                arm_vars.clone(),
                                check_child.clone(),
                                check_list.clone(),
                                si.clone(),
                            )
                        }) {
                            __all = false;
                            break;
                        }
                    }
                    __all
                };
                (scrut_ok.clone() && arms_ok.clone())
            }
            ExprData::ExprIf => {
                let cond_ok = all_self_calls_descend_inc(
                    if_condition(body.clone()),
                    func_name.clone(),
                    param_name.clone(),
                    vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    si.clone(),
                );
                let then_ok = all_self_calls_descend_inc(
                    if_then_branch(body.clone()),
                    func_name.clone(),
                    param_name.clone(),
                    vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    si.clone(),
                );
                let else_ok = match if_else_branch(body.clone()) {
                    Some(eb) => all_self_calls_descend_inc(
                        eb.clone(),
                        func_name.clone(),
                        param_name.clone(),
                        vars.clone(),
                        check_child.clone(),
                        check_list.clone(),
                        si.clone(),
                    ),
                    None => true,
                };
                ((cond_ok.clone() && then_ok.clone()) && else_ok.clone())
            }
            ExprData::ExprBlock => {
                let result = body.children.clone().iter().cloned().fold(
                    Arc::new(DescentCheckAcc {
                        ok: true,
                        vars: vars.clone(),
                    }),
                    |acc: Arc<DescentCheckAcc>, stmt: Arc<Node>| {
                        if (acc.ok.clone() == false) {
                            acc.clone()
                        } else {
                            {
                                let stmt_ok = all_self_calls_descend_inc(
                                    stmt.clone(),
                                    func_name.clone(),
                                    param_name.clone(),
                                    acc.vars.clone(),
                                    check_child.clone(),
                                    check_list.clone(),
                                    si.clone(),
                                );
                                let next_vars = collect_descent_vars(
                                    stmt.clone(),
                                    param_name.clone(),
                                    acc.vars.clone(),
                                    check_child.clone(),
                                    check_list.clone(),
                                    si.clone(),
                                );
                                Arc::new(DescentCheckAcc {
                                    ok: stmt_ok.clone(),
                                    vars: next_vars.clone(),
                                })
                            }
                        }
                    },
                );
                result.ok.clone()
            }
            ExprData::ExprCall { .. } => {
                let callee = expr_call_func_at(body.clone(), si.clone());
                let own_ok = if (callee.clone() == func_name.clone()) {
                    {
                        let mut __found = false;
                        for arg_node in body.children.clone().iter().cloned() {
                            if {
                                let targets_param = (arg_name_at(arg_node.clone(), si.clone())
                                    .as_deref()
                                    == Some(param_name.clone()).as_deref());
                                if (targets_param.clone() == false) {
                                    false
                                } else {
                                    is_descent_arg(
                                        arg_value(arg_node.clone()),
                                        param_name.clone(),
                                        vars.clone(),
                                        check_child.clone(),
                                        check_list.clone(),
                                        si.clone(),
                                    )
                                }
                            } {
                                __found = true;
                                break;
                            }
                        }
                        __found
                    }
                } else {
                    true
                };
                (own_ok.clone() && {
                    let mut __all = true;
                    for child in body.children.clone().iter().cloned() {
                        if !(all_self_calls_descend_inc(
                            child.clone(),
                            func_name.clone(),
                            param_name.clone(),
                            vars.clone(),
                            check_child.clone(),
                            check_list.clone(),
                            si.clone(),
                        )) {
                            __all = false;
                            break;
                        }
                    }
                    __all
                })
            }
            ExprData::ExprMethodCall {
                method_semantics: ms,
                ..
            } => {
                let receiver = method_receiver(body.clone());
                let is_iter = is_algebra_iteration_method(ms.clone());
                let is_struct = is_structural_children(
                    receiver.clone(),
                    param_name.clone(),
                    vars.clone(),
                    si.clone(),
                );
                if (is_iter.clone() && is_struct.clone()) {
                    {
                        let recv_ok = all_self_calls_descend_inc(
                            receiver.clone(),
                            func_name.clone(),
                            param_name.clone(),
                            vars.clone(),
                            check_child.clone(),
                            check_list.clone(),
                            si.clone(),
                        );
                        let args_ok = {
                            let mut __all = true;
                            for arg_node in method_arg_nodes(body.clone()).iter().cloned() {
                                if !({
                                    let arg_val = arg_value(arg_node.clone());
                                    match (*arg_val.expr_data.clone()).clone() {
                                        ExprData::ExprLambda => match iteration_element_name(
                                            ms.clone(),
                                            arg_val.clone(),
                                            si.clone(),
                                        ) {
                                            Some(iter_name) => {
                                                let ext_vars = v1_rt::rc_map_insert(
                                                    vars.clone(),
                                                    iter_name.clone(),
                                                    true,
                                                );
                                                all_self_calls_descend_inc(
                                                    lambda_body(arg_val.clone()),
                                                    func_name.clone(),
                                                    param_name.clone(),
                                                    ext_vars.clone(),
                                                    check_child.clone(),
                                                    check_list.clone(),
                                                    si.clone(),
                                                )
                                            }
                                            None => true,
                                        },
                                        _ => all_self_calls_descend_inc(
                                            arg_val.clone(),
                                            func_name.clone(),
                                            param_name.clone(),
                                            vars.clone(),
                                            check_child.clone(),
                                            check_list.clone(),
                                            si.clone(),
                                        ),
                                    }
                                }) {
                                    __all = false;
                                    break;
                                }
                            }
                            __all
                        };
                        (recv_ok.clone() && args_ok.clone())
                    }
                } else {
                    {
                        let mut __all = true;
                        for child in body.children.clone().iter().cloned() {
                            if !(all_self_calls_descend_inc(
                                child.clone(),
                                func_name.clone(),
                                param_name.clone(),
                                vars.clone(),
                                check_child.clone(),
                                check_list.clone(),
                                si.clone(),
                            )) {
                                __all = false;
                                break;
                            }
                        }
                        __all
                    }
                }
            }
            _ => {
                let mut __all = true;
                for child in body.children.clone().iter().cloned() {
                    if !(all_self_calls_descend_inc(
                        child.clone(),
                        func_name.clone(),
                        param_name.clone(),
                        vars.clone(),
                        check_child.clone(),
                        check_list.clone(),
                        si.clone(),
                    )) {
                        __all = false;
                        break;
                    }
                }
                __all
            }
        }
    })
}

pub fn unwrap_to_match(mut body: Arc<Node>) -> Option<Arc<Node>> {
    loop {
        match (*body.expr_data.clone()).clone() {
            ExprData::ExprMatch => {
                break Some(body.clone());
            }
            ExprData::ExprLet => match let_body(body.clone()) {
                Some(b) => {
                    let __tco_0 = b.clone();
                    body = __tco_0;
                    continue;
                }
                None => {
                    break None;
                }
            },
            ExprData::ExprBlock => match body.children.clone().last().cloned() {
                Some(last_stmt) => {
                    let __tco_0 = last_stmt.clone();
                    body = __tco_0;
                    continue;
                }
                None => {
                    break None;
                }
            },
            _ => {
                break None;
            }
        }
    }
}

pub fn matches_on_sub_value_field(
    body: Arc<Node>,
    param_name: String,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> bool {
    match unwrap_to_match(body.clone()) {
        Some(m) => {
            let scrut = match_scrutinee(m.clone());
            match (*scrut.expr_data.clone()).clone() {
                ExprData::ExprFieldAccess { .. } => {
                    let base = field_access_base(scrut.clone());
                    let field = field_access_field_at(scrut.clone(), si.clone());
                    (is_sub_value_field(field.clone())
                        && match (*base.expr_data.clone()).clone() {
                            ExprData::ExprVar {
                                binding_kind: _, ..
                            } => (expr_var_name_at(base.clone(), si.clone()) == param_name.clone()),
                            _ => false,
                        })
                }
                _ => false,
            }
        }
        None => false,
    }
}

pub fn is_container_child_descent(
    body: Arc<Node>,
    func_name: String,
    params: Arc<Vec<Arc<Node>>>,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> bool {
    {
        let mut __found = false;
        for p in params.clone().iter().cloned() {
            if {
                let pname = param_node_name_at(p.clone(), si.clone());
                (matches_on_sub_value_field(body.clone(), pname.clone(), si.clone())
                    && all_self_calls_descend(
                        body.clone(),
                        func_name.clone(),
                        pname.clone(),
                        true,
                        false,
                        si.clone(),
                    ))
            } {
                __found = true;
                break;
            }
        }
        __found
    }
}

pub fn is_list_shrinkage_descent(
    body: Arc<Node>,
    func_name: String,
    params: Arc<Vec<Arc<Node>>>,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> bool {
    {
        let mut __found = false;
        for p in params.clone().iter().cloned() {
            if {
                let pname = param_node_name_at(p.clone(), si.clone());
                all_self_calls_descend(
                    body.clone(),
                    func_name.clone(),
                    pname.clone(),
                    false,
                    true,
                    si.clone(),
                )
            } {
                __found = true;
                break;
            }
        }
        __found
    }
}

pub fn is_arithmetic_descent_expr(
    expr: Arc<Node>,
    param_name: String,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> bool {
    match (*expr.expr_data.clone()).clone() {
        ExprData::ExprBinOp { op: BinOp::Sub, .. } => {
            let left = binop_left(expr.clone());
            let right = binop_right(expr.clone());
            match (*left.expr_data.clone()).clone() {
                ExprData::ExprVar {
                    binding_kind: _, ..
                } => {
                    ((expr_var_name_at(left.clone(), si.clone()) == param_name.clone())
                        && match (*right.expr_data.clone()).clone() {
                            ExprData::ExprLiteral { ref value, .. } => {
                                let LiteralValue::LitInt { value: n, .. } = value.as_ref() else {
                                    unreachable!()
                                };
                                (n.clone() > 0)
                            }
                            _ => false,
                        })
                }
                _ => false,
            }
        }
        _ => false,
    }
}

pub fn classify_self_call_evidence(
    arg_expr: Arc<Node>,
    param_name: String,
    descent_vars: Arc<HashMap<String, bool>>,
    check_child: bool,
    check_list: bool,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> DescentEvidence {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        if (check_child.clone()
            && is_child_descent_expr(
                arg_expr.clone(),
                param_name.clone(),
                descent_vars.clone(),
                si.clone(),
            ))
        {
            DescentEvidence::Strict
        } else {
            if (check_list.clone()
                && is_list_shrink_expr(arg_expr.clone(), param_name.clone(), si.clone()))
            {
                DescentEvidence::Strict
            } else {
                if (((check_child.clone() == false) && (check_list.clone() == false))
                    && is_arithmetic_descent_expr(arg_expr.clone(), param_name.clone(), si.clone()))
                {
                    DescentEvidence::Strict
                } else {
                    match (*arg_expr.expr_data.clone()).clone() {
                        ExprData::ExprVar {
                            binding_kind: _, ..
                        } => {
                            let vname = expr_var_name_at(arg_expr.clone(), si.clone());
                            if set_has(descent_vars.clone(), vname.clone()) {
                                DescentEvidence::Strict
                            } else {
                                if (vname.clone() == param_name.clone()) {
                                    DescentEvidence::NonIncreasing
                                } else {
                                    DescentEvidence::DescentUnknown
                                }
                            }
                        }
                        ExprData::ExprCall { .. } => {
                            if is_tree_size_preserving_wrapper(arg_expr.clone(), si.clone()) {
                                classify_self_call_evidence(
                                    wrapper_inner_arg(arg_expr.clone()),
                                    param_name.clone(),
                                    descent_vars.clone(),
                                    check_child.clone(),
                                    check_list.clone(),
                                    si.clone(),
                                )
                            } else {
                                if is_sub_value_extractor(arg_expr.clone(), si.clone()) {
                                    {
                                        let inner_ev = classify_self_call_evidence(
                                            extractor_inner_arg(arg_expr.clone()),
                                            param_name.clone(),
                                            descent_vars.clone(),
                                            check_child.clone(),
                                            check_list.clone(),
                                            si.clone(),
                                        );
                                        match inner_ev.clone() {
                                            DescentEvidence::NonIncreasing => {
                                                DescentEvidence::Strict
                                            }
                                            _ => inner_ev.clone(),
                                        }
                                    }
                                } else {
                                    if is_list_passthrough_call(arg_expr.clone(), si.clone()) {
                                        match list_passthrough_inner_arg(
                                            arg_expr.clone(),
                                            si.clone(),
                                        ) {
                                            Some(inner) => classify_self_call_evidence(
                                                inner.clone(),
                                                param_name.clone(),
                                                descent_vars.clone(),
                                                check_child.clone(),
                                                check_list.clone(),
                                                si.clone(),
                                            ),
                                            None => DescentEvidence::DescentUnknown,
                                        }
                                    } else {
                                        DescentEvidence::DescentUnknown
                                    }
                                }
                            }
                        }
                        ExprData::ExprFieldAccess { .. } => {
                            let base = field_access_base(arg_expr.clone());
                            match (*base.expr_data.clone()).clone() {
                                ExprData::ExprVar {
                                    binding_kind: _, ..
                                } => {
                                    let bname = expr_var_name_at(base.clone(), si.clone());
                                    if (set_has(descent_vars.clone(), bname.clone())
                                        || (bname.clone() == param_name.clone()))
                                    {
                                        DescentEvidence::Strict
                                    } else {
                                        {
                                            let field =
                                                field_access_field_at(arg_expr.clone(), si.clone());
                                            if (field.clone() == param_name.clone()) {
                                                DescentEvidence::NonIncreasing
                                            } else {
                                                DescentEvidence::DescentUnknown
                                            }
                                        }
                                    }
                                }
                                _ => DescentEvidence::DescentUnknown,
                            }
                        }
                        ExprData::ExprMethodCall {
                            method_semantics: ms,
                            ..
                        } => {
                            if is_generalized_shrink(arg_expr.clone(), si.clone()) {
                                {
                                    let recv = method_receiver(arg_expr.clone());
                                    let recv_ev = classify_self_call_evidence(
                                        recv.clone(),
                                        param_name.clone(),
                                        descent_vars.clone(),
                                        check_child.clone(),
                                        check_list.clone(),
                                        si.clone(),
                                    );
                                    match recv_ev.clone() {
                                        DescentEvidence::Strict => DescentEvidence::Strict,
                                        DescentEvidence::NonIncreasing => DescentEvidence::Strict,
                                        DescentEvidence::DescentUnknown => {
                                            DescentEvidence::DescentUnknown
                                        }
                                    }
                                }
                            } else {
                                DescentEvidence::DescentUnknown
                            }
                        }
                        _ => DescentEvidence::DescentUnknown,
                    }
                }
            }
        }
    })
}

