pub fn merge_optional_evidence(
    a: Option<DescentEvidence>,
    b: Option<DescentEvidence>,
) -> Option<DescentEvidence> {
    optional_evidence_meet(a.clone(), b.clone())
}

pub fn collect_evidence_incremental(
    body: Arc<Node>,
    func_name: String,
    param_name: String,
    vars: Arc<HashMap<String, bool>>,
    check_child: bool,
    check_list: bool,
    branching_only: bool,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> Option<DescentEvidence> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*body.expr_data.clone()).clone() {
            ExprData::ExprLambda => None,
            ExprData::ExprLet => {
                let val = let_value(body.clone());
                let val_ev = collect_evidence_incremental(
                    val.clone(),
                    func_name.clone(),
                    param_name.clone(),
                    vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    branching_only.clone(),
                    si.clone(),
                );
                let is_direct = ((check_child.clone()
                    && is_child_descent_expr(
                        val.clone(),
                        param_name.clone(),
                        vars.clone(),
                        si.clone(),
                    ))
                    || (check_list.clone()
                        && is_list_shrink_expr(val.clone(), param_name.clone(), si.clone())));
                let is_var = match (*val.expr_data.clone()).clone() {
                    ExprData::ExprVar {
                        binding_kind: _, ..
                    } => set_has(vars.clone(), expr_var_name_at(val.clone(), si.clone())),
                    _ => false,
                };
                let is_option = is_if_option_descent(
                    val.clone(),
                    param_name.clone(),
                    vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    si.clone(),
                );
                let is_match_descent = is_match_option_descent(
                    val.clone(),
                    param_name.clone(),
                    vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    si.clone(),
                );
                let is_wrapped = if is_tree_size_preserving_wrapper(val.clone(), si.clone()) {
                    {
                        let inner = wrapper_inner_arg(val.clone());
                        let inner_d = ((check_child.clone()
                            && is_child_descent_expr(
                                inner.clone(),
                                param_name.clone(),
                                vars.clone(),
                                si.clone(),
                            ))
                            || (check_list.clone()
                                && is_list_shrink_expr(
                                    inner.clone(),
                                    param_name.clone(),
                                    si.clone(),
                                )));
                        let inner_v = match (*inner.expr_data.clone()).clone() {
                            ExprData::ExprVar {
                                binding_kind: _, ..
                            } => set_has(vars.clone(), expr_var_name_at(inner.clone(), si.clone())),
                            _ => false,
                        };
                        (inner_d.clone() || inner_v.clone())
                    }
                } else {
                    false
                };
                let is_extraction = if is_sub_value_extractor(val.clone(), si.clone()) {
                    {
                        let inner = extractor_inner_arg(val.clone());
                        let inner_d = ((check_child.clone()
                            && is_child_descent_expr(
                                inner.clone(),
                                param_name.clone(),
                                vars.clone(),
                                si.clone(),
                            ))
                            || (check_list.clone()
                                && is_list_shrink_expr(
                                    inner.clone(),
                                    param_name.clone(),
                                    si.clone(),
                                )));
                        let inner_v = match (*inner.expr_data.clone()).clone() {
                            ExprData::ExprVar {
                                binding_kind: _, ..
                            } => set_has(vars.clone(), expr_var_name_at(inner.clone(), si.clone())),
                            _ => false,
                        };
                        let inner_p = match (*inner.expr_data.clone()).clone() {
                            ExprData::ExprVar {
                                binding_kind: _, ..
                            } => {
                                (expr_var_name_at(inner.clone(), si.clone()) == param_name.clone())
                            }
                            _ => false,
                        };
                        ((inner_d.clone() || inner_v.clone()) || inner_p.clone())
                    }
                } else {
                    false
                };
                let is_children_list = match (*val.expr_data.clone()).clone() {
                    ExprData::ExprFieldAccess { .. } => {
                        let base = field_access_base(val.clone());
                        let field = field_access_field_at(val.clone(), si.clone());
                        (is_children_list_field(field.clone())
                            && match (*base.expr_data.clone()).clone() {
                                ExprData::ExprVar {
                                    binding_kind: _, ..
                                } => {
                                    let bname = expr_var_name_at(base.clone(), si.clone());
                                    ((bname.clone() == param_name.clone())
                                        || set_has(vars.clone(), bname.clone()))
                                }
                                _ => false,
                            })
                    }
                    _ => false,
                };
                let is_passthrough = if is_list_passthrough_call(val.clone(), si.clone()) {
                    match list_passthrough_inner_arg(val.clone(), si.clone()) {
                        Some(inner) => {
                            (((check_child.clone()
                                && is_child_descent_expr(
                                    inner.clone(),
                                    param_name.clone(),
                                    vars.clone(),
                                    si.clone(),
                                ))
                                || (check_list.clone()
                                    && is_list_shrink_expr(
                                        inner.clone(),
                                        param_name.clone(),
                                        si.clone(),
                                    )))
                                || match (*inner.expr_data.clone()).clone() {
                                    ExprData::ExprVar {
                                        binding_kind: _, ..
                                    } => set_has(
                                        vars.clone(),
                                        expr_var_name_at(inner.clone(), si.clone()),
                                    ),
                                    _ => false,
                                })
                        }
                        None => false,
                    }
                } else {
                    false
                };
                let is_consuming_helper = (check_list.clone()
                    && is_tokens_consuming_call(
                        val.clone(),
                        param_name.clone(),
                        vars.clone(),
                        si.clone(),
                    ));
                let next_vars = if ((((((((is_direct.clone() || is_var.clone())
                    || is_option.clone())
                    || is_match_descent.clone())
                    || is_wrapped.clone())
                    || is_extraction.clone())
                    || is_children_list.clone())
                    || is_passthrough.clone())
                    || is_consuming_helper.clone())
                {
                    v1_rt::rc_map_insert(
                        vars.clone(),
                        let_binding_name_at(body.clone(), si.clone()),
                        true,
                    )
                } else {
                    vars.clone()
                };
                let body_ev = match let_body(body.clone()) {
                    Some(b) => collect_evidence_incremental(
                        b.clone(),
                        func_name.clone(),
                        param_name.clone(),
                        next_vars.clone(),
                        check_child.clone(),
                        check_list.clone(),
                        branching_only.clone(),
                        si.clone(),
                    ),
                    None => None,
                };
                merge_optional_evidence(val_ev.clone(), body_ev.clone())
            }
            ExprData::ExprMatch => {
                let scrut = match_scrutinee(body.clone());
                let scrut_ev = collect_evidence_incremental(
                    scrut.clone(),
                    func_name.clone(),
                    param_name.clone(),
                    vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    branching_only.clone(),
                    si.clone(),
                );
                let scrut_is_descent = expr_contains_descent(
                    scrut.clone(),
                    param_name.clone(),
                    vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    si.clone(),
                );
                let scrut_is_param = match (*scrut.expr_data.clone()).clone() {
                    ExprData::ExprVar {
                        binding_kind: _, ..
                    } => {
                        let sname = expr_var_name_at(scrut.clone(), si.clone());
                        ((sname.clone() == param_name.clone())
                            || set_has(vars.clone(), sname.clone()))
                    }
                    _ => false,
                };
                let arms_ev = match_arm_nodes(body.clone()).iter().cloned().fold(
                    None,
                    |acc: _, arm_node: Arc<Node>| {
                        let is_base_case = if branching_only.clone() {
                            (max_path_self_calls(
                                arm_body(arm_node.clone()),
                                func_name.clone(),
                                si.clone(),
                            ) == 0)
                        } else {
                            false
                        };
                        if is_base_case.clone() {
                            acc.clone()
                        } else {
                            {
                                let arm_vars =
                                    if (scrut_is_descent.clone() || scrut_is_param.clone()) {
                                        match (*arm_pattern(arm_node.clone())).clone() {
                                            MatchPattern::VariantPattern {
                                                field_bindings: bindings,
                                                ..
                                            } => bindings.clone().iter().cloned().fold(
                                                vars.clone(),
                                                |inner: Arc<HashMap<String, bool>>, fb: Arc<Node>| {
                                                    collect_field_binding_names(fb.clone(), inner)
                                                },
                                            ),
                                            MatchPattern::Bind {
                                                name: binding_name, ..
                                            } => {
                                                if scrut_is_descent.clone() {
                                                    v1_rt::rc_map_insert(
                                                        vars.clone(),
                                                        binding_name.clone(),
                                                        true,
                                                    )
                                                } else {
                                                    vars.clone()
                                                }
                                            }
                                            _ => vars.clone(),
                                        }
                                    } else {
                                        vars.clone()
                                    };
                                let arm_ev = collect_evidence_incremental(
                                    arm_body(arm_node.clone()),
                                    func_name.clone(),
                                    param_name.clone(),
                                    arm_vars.clone(),
                                    check_child.clone(),
                                    check_list.clone(),
                                    branching_only.clone(),
                                    si.clone(),
                                );
                                merge_optional_evidence(acc.clone(), arm_ev.clone())
                            }
                        }
                    },
                );
                merge_optional_evidence(scrut_ev.clone(), arms_ev.clone())
            }
            ExprData::ExprIf => {
                let cond_ev = collect_evidence_incremental(
                    if_condition(body.clone()),
                    func_name.clone(),
                    param_name.clone(),
                    vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    branching_only.clone(),
                    si.clone(),
                );
                let then_branch = if_then_branch(body.clone());
                let else_opt = if_else_branch(body.clone());
                let then_path = if branching_only.clone() {
                    max_path_self_calls(then_branch.clone(), func_name.clone(), si.clone())
                } else {
                    0
                };
                let else_path = if branching_only.clone() {
                    match else_opt.clone() {
                        Some(eb) => max_path_self_calls(eb.clone(), func_name.clone(), si.clone()),
                        None => 0,
                    }
                } else {
                    0
                };
                let then_ev = if (branching_only.clone() && (then_path.clone() == 0)) {
                    None
                } else {
                    collect_evidence_incremental(
                        then_branch.clone(),
                        func_name.clone(),
                        param_name.clone(),
                        vars.clone(),
                        check_child.clone(),
                        check_list.clone(),
                        branching_only.clone(),
                        si.clone(),
                    )
                };
                let else_ev = if (branching_only.clone() && (else_path.clone() == 0)) {
                    None
                } else {
                    match else_opt.clone() {
                        Some(eb) => collect_evidence_incremental(
                            eb.clone(),
                            func_name.clone(),
                            param_name.clone(),
                            vars.clone(),
                            check_child.clone(),
                            check_list.clone(),
                            branching_only.clone(),
                            si.clone(),
                        ),
                        None => None,
                    }
                };
                merge_optional_evidence(
                    cond_ev.clone(),
                    merge_optional_evidence(then_ev.clone(), else_ev.clone()),
                )
            }
            ExprData::ExprCall { .. } => {
                let callee = expr_call_func_at(body.clone(), si.clone());
                let own_evidence = if (callee.clone() == func_name.clone()) {
                    {
                        let arg_evidence = body.children.clone().iter().cloned().fold(
                            DescentEvidence::DescentUnknown,
                            |acc: DescentEvidence, arg_node: Arc<Node>| {
                                let aname = arg_name_at(arg_node.clone(), si.clone());
                                if (aname.clone().as_deref() == Some(param_name.clone()).as_deref())
                                {
                                    classify_self_call_evidence(
                                        arg_value(arg_node.clone()),
                                        param_name.clone(),
                                        vars.clone(),
                                        check_child.clone(),
                                        check_list.clone(),
                                        si.clone(),
                                    )
                                } else {
                                    acc
                                }
                            },
                        );
                        Some(arg_evidence.clone())
                    }
                } else {
                    None
                };
                let child_evidence =
                    body.children
                        .clone()
                        .iter()
                        .cloned()
                        .fold(None, |acc: _, child: Arc<Node>| {
                            let ce = collect_evidence_incremental(
                                child.clone(),
                                func_name.clone(),
                                param_name.clone(),
                                vars.clone(),
                                check_child.clone(),
                                check_list.clone(),
                                branching_only.clone(),
                                si.clone(),
                            );
                            merge_optional_evidence(acc.clone(), ce.clone())
                        });
                merge_optional_evidence(own_evidence.clone(), child_evidence.clone())
            }
            ExprData::ExprBlock => {
                let result = body.children.clone().iter().cloned().fold(
                    Arc::new(EvidenceBlockAcc {
                        evidence: None,
                        vars: vars.clone(),
                    }),
                    |acc: Arc<EvidenceBlockAcc>, stmt: Arc<Node>| {
                        let stmt_ev = collect_evidence_incremental(
                            stmt.clone(),
                            func_name.clone(),
                            param_name.clone(),
                            acc.vars.clone(),
                            check_child.clone(),
                            check_list.clone(),
                            branching_only.clone(),
                            si.clone(),
                        );
                        let next_vars = collect_descent_vars(
                            stmt.clone(),
                            param_name.clone(),
                            acc.vars.clone(),
                            check_child.clone(),
                            check_list.clone(),
                            si.clone(),
                        );
                        Arc::new(EvidenceBlockAcc {
                            evidence: merge_optional_evidence(
                                acc.evidence.clone(),
                                stmt_ev.clone(),
                            ),
                            vars: next_vars.clone(),
                        })
                    },
                );
                result.evidence.clone()
            }
            ExprData::ExprMethodCall {
                method_semantics: ms,
                ..
            } => {
                let receiver = method_receiver(body.clone());
                let is_iter = is_algebra_iteration_method(ms.clone());
                let is_struct = is_structural_children(
                    receiver.clone(),
                    param_name.clone(),
                    vars.clone(),
                    si.clone(),
                );
                if (is_iter.clone() && is_struct.clone()) {
                    {
                        let recv_ev = collect_evidence_incremental(
                            receiver.clone(),
                            func_name.clone(),
                            param_name.clone(),
                            vars.clone(),
                            check_child.clone(),
                            check_list.clone(),
                            branching_only.clone(),
                            si.clone(),
                        );
                        let args_ev = method_arg_nodes(body.clone()).iter().cloned().fold(
                            None,
                            |acc: _, arg_node: Arc<Node>| {
                                let arg_val = arg_value(arg_node.clone());
                                let ev = match (*arg_val.expr_data.clone()).clone() {
                                    ExprData::ExprLambda => match iteration_element_name(
                                        ms.clone(),
                                        arg_val.clone(),
                                        si.clone(),
                                    ) {
                                        Some(iter_name) => {
                                            let ext_vars = v1_rt::rc_map_insert(
                                                vars.clone(),
                                                iter_name.clone(),
                                                true,
                                            );
                                            collect_evidence_incremental(
                                                lambda_body(arg_val.clone()),
                                                func_name.clone(),
                                                param_name.clone(),
                                                ext_vars.clone(),
                                                check_child.clone(),
                                                check_list.clone(),
                                                branching_only.clone(),
                                                si.clone(),
                                            )
                                        }
                                        None => None,
                                    },
                                    _ => collect_evidence_incremental(
                                        arg_val.clone(),
                                        func_name.clone(),
                                        param_name.clone(),
                                        vars.clone(),
                                        check_child.clone(),
                                        check_list.clone(),
                                        branching_only.clone(),
                                        si.clone(),
                                    ),
                                };
                                merge_optional_evidence(acc.clone(), ev.clone())
                            },
                        );
                        merge_optional_evidence(recv_ev.clone(), args_ev.clone())
                    }
                } else {
                    body.children
                        .clone()
                        .iter()
                        .cloned()
                        .fold(None, |acc: _, child: Arc<Node>| {
                            let ce = collect_evidence_incremental(
                                child.clone(),
                                func_name.clone(),
                                param_name.clone(),
                                vars.clone(),
                                check_child.clone(),
                                check_list.clone(),
                                branching_only.clone(),
                                si.clone(),
                            );
                            merge_optional_evidence(acc.clone(), ce.clone())
                        })
                }
            }
            _ => body
                .children
                .clone()
                .iter()
                .cloned()
                .fold(None, |acc: _, child: Arc<Node>| {
                    let ce = collect_evidence_incremental(
                        child.clone(),
                        func_name.clone(),
                        param_name.clone(),
                        vars.clone(),
                        check_child.clone(),
                        check_list.clone(),
                        branching_only.clone(),
                        si.clone(),
                    );
                    merge_optional_evidence(acc.clone(), ce.clone())
                }),
        }
    })
}

pub fn try_type_directed_dimension(
    body: Arc<Node>,
    func_name: String,
    param_name: String,
    dim: IterationDimension,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> Option<Arc<TerminationProof>> {
    match dim.clone() {
        IterationDimension::TreeDescent => match try_dimension_for_param(
            body.clone(),
            func_name.clone(),
            param_name.clone(),
            true,
            false,
            si.clone(),
        ) {
            Some(DescentEvidence::Strict) => Some(Arc::new(TerminationProof {
                dimensions: Arc::new(vec![Arc::new(RankingDimension::TreeSize {
                    param: param_name.clone(),
                })]),
            })),
            _ => None,
        },
        IterationDimension::CollectionFold => match try_dimension_for_param(
            body.clone(),
            func_name.clone(),
            param_name.clone(),
            false,
            true,
            si.clone(),
        ) {
            Some(DescentEvidence::Strict) => Some(Arc::new(TerminationProof {
                dimensions: Arc::new(vec![Arc::new(RankingDimension::ListLength {
                    param: param_name.clone(),
                })]),
            })),
            _ => None,
        },
        IterationDimension::ArithmeticRepeat => match try_dimension_for_param(
            body.clone(),
            func_name.clone(),
            param_name.clone(),
            false,
            false,
            si.clone(),
        ) {
            Some(DescentEvidence::Strict) => Some(Arc::new(TerminationProof {
                dimensions: Arc::new(vec![Arc::new(RankingDimension::ArithmeticValue {
                    param: param_name.clone(),
                })]),
            })),
            _ => None,
        },
    }
}

pub fn construct_termination_proof(
    func_name: String,
    body: Arc<Node>,
    params: Arc<Vec<Arc<Node>>>,
    parser_always_advancing: Arc<HashMap<String, bool>>,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> Option<Arc<TerminationProof>> {
    {
        let structural_proof =
            params
                .clone()
                .iter()
                .cloned()
                .fold(None, |best: _, p: Arc<Node>| match best.clone() {
                    Some(_) => best.clone(),
                    None => {
                        let pname = param_node_name_at(p.clone(), si.clone());
                        let type_name =
                            authored_name_at(si.clone(), param_node_type_expr(p.clone()));
                        match type_iteration_dimension(type_name.clone()) {
                            Some(dim) => try_type_directed_dimension(
                                body.clone(),
                                func_name.clone(),
                                pname.clone(),
                                dim.clone(),
                                si.clone(),
                            ),
                            None => {
                                let tree_evidence = try_dimension_for_param(
                                    body.clone(),
                                    func_name.clone(),
                                    pname.clone(),
                                    true,
                                    false,
                                    si.clone(),
                                );
                                match tree_evidence.clone() {
                                    Some(DescentEvidence::Strict) => {
                                        Some(Arc::new(TerminationProof {
                                            dimensions: Arc::new(vec![Arc::new(
                                                RankingDimension::TreeSize {
                                                    param: pname.clone(),
                                                },
                                            )]),
                                        }))
                                    }
                                    _ => {
                                        let list_evidence = try_dimension_for_param(
                                            body.clone(),
                                            func_name.clone(),
                                            pname.clone(),
                                            false,
                                            true,
                                            si.clone(),
                                        );
                                        match list_evidence.clone() {
                                            Some(DescentEvidence::Strict) => {
                                                Some(Arc::new(TerminationProof {
                                                    dimensions: Arc::new(vec![Arc::new(
                                                        RankingDimension::ListLength {
                                                            param: pname.clone(),
                                                        },
                                                    )]),
                                                }))
                                            }
                                            _ => {
                                                let arith_evidence = try_dimension_for_param(
                                                    body.clone(),
                                                    func_name.clone(),
                                                    pname.clone(),
                                                    false,
                                                    false,
                                                    si.clone(),
                                                );
                                                match arith_evidence.clone() {
                                                    Some(DescentEvidence::Strict) => {
                                                        Some(Arc::new(TerminationProof {
                                                            dimensions: Arc::new(vec![Arc::new(
                                                                RankingDimension::ArithmeticValue {
                                                                    param: pname.clone(),
                                                                },
                                                            )]),
                                                        }))
                                                    }
                                                    _ => None,
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                });
        let single_dim_proof = match structural_proof.clone() {
            Some(_) => structural_proof.clone(),
            None => match parser_state_param(params.clone(), si.clone()) {
                Some(state_param) => {
                    let self_set = seed_bool_map(func_name.clone());
                    let edges = collect_parser_progress_edges(
                        func_name.clone(),
                        body.clone(),
                        state_param.clone(),
                        self_set.clone(),
                        empty_parser_progress_env(),
                        parser_always_advancing.clone(),
                        v1_rt::rc_empty_map::<String, bool>(),
                        si.clone(),
                    );
                    if (((edges.clone().len() as i64) > 0) && {
                        let mut __all = true;
                        for edge in edges.clone().iter().cloned() {
                            if !(edge.progress.clone() == DescentEvidence::Strict) {
                                __all = false;
                                break;
                            }
                        }
                        __all
                    }) {
                        Some(Arc::new(TerminationProof {
                            dimensions: Arc::new(vec![Arc::new(RankingDimension::TokenPosition {
                                param: state_param.name.clone(),
                            })]),
                        }))
                    } else {
                        None
                    }
                }
                None => None,
            },
        };
        match single_dim_proof.clone() {
            Some(_) => single_dim_proof.clone(),
            None => {
                let self_set = seed_bool_map(func_name.clone());
                let func_entry = Arc::new(FuncEntry {
                    name: func_name.clone(),
                    body: body.clone(),
                    params: params.clone(),
                    span: body.span.clone(),
                    is_tail_recursive: false,
                });
                let func_index = seed_func_entry_map(func_name.clone(), func_entry.clone());
                construct_scc_termination_proof(
                    Arc::new(vec![func_name.clone()]),
                    func_index.clone(),
                    self_set.clone(),
                    si.clone(),
                )
            }
        }
    }
}

pub fn construct_branching_termination_proof(
    func_name: String,
    body: Arc<Node>,
    params: Arc<Vec<Arc<Node>>>,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> Option<Arc<TerminationProof>> {
    params
        .clone()
        .iter()
        .cloned()
        .fold(None, |best: _, p: Arc<Node>| match best.clone() {
            Some(_) => best.clone(),
            None => {
                let pname = param_node_name_at(p.clone(), si.clone());
                let type_name = authored_name_at(si.clone(), param_node_type_expr(p.clone()));
                match type_iteration_dimension(type_name.clone()) {
                    Some(IterationDimension::TreeDescent) => {
                        match try_branching_dimension_for_param(
                            body.clone(),
                            func_name.clone(),
                            pname.clone(),
                            true,
                            false,
                            si.clone(),
                        ) {
                            Some(DescentEvidence::Strict) => Some(Arc::new(TerminationProof {
                                dimensions: Arc::new(vec![Arc::new(RankingDimension::TreeSize {
                                    param: pname.clone(),
                                })]),
                            })),
                            _ => None,
                        }
                    }
                    Some(IterationDimension::CollectionFold) => {
                        match try_branching_dimension_for_param(
                            body.clone(),
                            func_name.clone(),
                            pname.clone(),
                            false,
                            true,
                            si.clone(),
                        ) {
                            Some(DescentEvidence::Strict) => Some(Arc::new(TerminationProof {
                                dimensions: Arc::new(vec![Arc::new(
                                    RankingDimension::ListLength {
                                        param: pname.clone(),
                                    },
                                )]),
                            })),
                            _ => None,
                        }
                    }
                    Some(IterationDimension::ArithmeticRepeat) => None,
                    None => {
                        let tree_ev = try_branching_dimension_for_param(
                            body.clone(),
                            func_name.clone(),
                            pname.clone(),
                            true,
                            false,
                            si.clone(),
                        );
                        match tree_ev.clone() {
                            Some(DescentEvidence::Strict) => Some(Arc::new(TerminationProof {
                                dimensions: Arc::new(vec![Arc::new(RankingDimension::TreeSize {
                                    param: pname.clone(),
                                })]),
                            })),
                            _ => {
                                let list_ev = try_branching_dimension_for_param(
                                    body.clone(),
                                    func_name.clone(),
                                    pname.clone(),
                                    false,
                                    true,
                                    si.clone(),
                                );
                                match list_ev.clone() {
                                    Some(DescentEvidence::Strict) => {
                                        Some(Arc::new(TerminationProof {
                                            dimensions: Arc::new(vec![Arc::new(
                                                RankingDimension::ListLength {
                                                    param: pname.clone(),
                                                },
                                            )]),
                                        }))
                                    }
                                    _ => None,
                                }
                            }
                        }
                    }
                }
            }
        })
}

pub fn proof_to_call_pattern(proof: Arc<TerminationProof>) -> Arc<CallPattern> {
    match proof.dimensions.clone().first().cloned() {
        Some(dim) => match (*dim.clone()).clone() {
            RankingDimension::TreeSize { param: p, .. } => {
                Arc::new(CallPattern::ChildAccessorCall {
                    accessor: p.clone(),
                })
            }
            RankingDimension::ListLength { param: p, .. } => {
                Arc::new(CallPattern::CollectionShrinkCall {
                    amount: Arc::new(PositiveDescentAmount::OneStep),
                    collection: p.clone(),
                })
            }
            RankingDimension::ArithmeticValue { param: p, .. } => {
                Arc::new(CallPattern::ArithmeticSubtractCall {
                    steps: Arc::new(PositiveDescentAmount::OneStep),
                    ring_param: p.clone(),
                })
            }
            RankingDimension::TokenPosition { param: p, .. } => {
                Arc::new(CallPattern::ParserAdvanceCall { witness: p.clone() })
            }
            RankingDimension::SetCardinality { param: p, .. } => {
                Arc::new(CallPattern::WorklistDrainCall { element: p.clone() })
            }
        },
        None => Arc::new(CallPattern::SameArgumentCall),
    }
}

pub fn classify_recursion_pattern(
    func_name: String,
    body: Arc<Node>,
    params: Arc<Vec<Arc<Node>>>,
    parser_always_advancing: Arc<HashMap<String, bool>>,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> Arc<LoweringTarget> {
    {
        let path_calls = max_path_self_calls(body.clone(), func_name.clone(), si.clone());
        if (path_calls.clone() == 0) {
            {
                let outer = match params.clone().first().cloned() {
                    Some(p0) => param_node_name_at(p0.clone(), si.clone()),
                    None => "_fold_body".to_string(),
                };
                lower_call_pattern(Arc::new(CallPattern::FoldBodyCall {
                    outer_collection: outer.clone(),
                }))
            }
        } else {
            {
                let all_evidence =
                    collect_self_call_evidence(body.clone(), func_name.clone(), si.clone());
                let has_evidence = ((all_evidence.clone().len() as i64) > 0);
                let all_structural = (has_evidence.clone() && {
                    let mut __all = true;
                    for call_ev in all_evidence.clone().iter().cloned() {
                        if !({
                            let mut __found = false;
                            for rel in call_ev.clone().iter().cloned() {
                                if match (*rel.clone()).clone() {
                                    SubValueRelation::StrictSubValue { .. } => true,
                                    SubValueRelation::IteratedSubValue { field: _, .. } => true,
                                    SubValueRelation::ArithmeticDescent { .. } => true,
                                    _ => false,
                                } {
                                    __found = true;
                                    break;
                                }
                            }
                            __found
                        }) {
                            __all = false;
                            break;
                        }
                    }
                    __all
                });
                if all_structural.clone() {
                    {
                        let all_calls_arithmetic_only = {
                            let mut __all = true;
                            for call_ev in all_evidence.clone().iter().cloned() {
                                if !({
                                    let has_tree = {
                                        let mut __found = false;
                                        for rel in call_ev.clone().iter().cloned() {
                                            if match (*rel.clone()).clone() {
                                                SubValueRelation::StrictSubValue { .. } => true,
                                                SubValueRelation::IteratedSubValue {
                                                    field: _,
                                                    ..
                                                } => true,
                                                _ => false,
                                            } {
                                                __found = true;
                                                break;
                                            }
                                        }
                                        __found
                                    };
                                    let has_arith = {
                                        let mut __found = false;
                                        for rel in call_ev.clone().iter().cloned() {
                                            if match (*rel.clone()).clone() {
                                                SubValueRelation::ArithmeticDescent { .. } => true,
                                                _ => false,
                                            } {
                                                __found = true;
                                                break;
                                            }
                                        }
                                        __found
                                    };
                                    (has_arith.clone() && !has_tree.clone())
                                }) {
                                    __all = false;
                                    break;
                                }
                            }
                            __all
                        };
                        let first_call = if all_calls_arithmetic_only.clone() {
                            Arc::new({
                                let mut __result = Vec::new();
                                for call_ev in all_evidence.clone().iter().cloned() {
                                    __result.extend(
                                        (*Arc::new({
                                            let mut __result = Vec::new();
                                            for rel in call_ev.clone().iter().cloned() {
                                                if match (*rel.clone()).clone() {
                                                    SubValueRelation::ArithmeticDescent {
                                                        ..
                                                    } => true,
                                                    _ => false,
                                                } {
                                                    __result.push(rel);
                                                }
                                            }
                                            __result
                                        }))
                                        .iter()
                                        .cloned(),
                                    );
                                }
                                __result
                            })
                            .first()
                            .cloned()
                        } else {
                            {
                                let tree_rels =
                                    Arc::new({
                                        let mut __result = Vec::new();
                                        for call_ev in all_evidence.clone().iter().cloned() {
                                            __result.extend(
                                                (*Arc::new({
                                                    let mut __result = Vec::new();
                                                    for rel in call_ev.clone().iter().cloned() {
                                                        if match (*rel.clone()).clone() {
    SubValueRelation::StrictSubValue { .. } => true,
    SubValueRelation::IteratedSubValue { field: _, .. } => true,
    _ => false,
} { __result.push(rel); }
                                                    }
                                                    __result
                                                }))
                                                .iter()
                                                .cloned(),
                                            );
                                        }
                                        __result
                                    });
                                match tree_rels.clone().first().cloned() {
                                    Some(_) => tree_rels.clone().first().cloned(),
                                    None => Arc::new({
                                        let mut __result = Vec::new();
                                        for call_ev in all_evidence.clone().iter().cloned() {
                                            __result.extend(
                                                (*Arc::new({
                                                    let mut __result = Vec::new();
                                                    for rel in call_ev.clone().iter().cloned() {
                                                        if match (*rel.clone()).clone() {
    SubValueRelation::ArithmeticDescent { .. } => true,
    _ => false,
} { __result.push(rel); }
                                                    }
                                                    __result
                                                }))
                                                .iter()
                                                .cloned(),
                                            );
                                        }
                                        __result
                                    })
                                    .first()
                                    .cloned(),
                                }
                            }
                        };
                        let is_arithmetic_branching = match first_call.clone() {
                            Some(rel) => match (*rel.clone()).clone() {
                                SubValueRelation::ArithmeticDescent { .. } => {
                                    (path_calls.clone() > 1)
                                }
                                _ => false,
                            },
                            None => false,
                        };
                        if is_arithmetic_branching.clone() {
                            lower_call_pattern(Arc::new(CallPattern::SameArgumentCall))
                        } else {
                            match first_call.clone() {
                                Some(rel) => match sub_value_to_lowering_target(rel.clone()) {
                                    Some(target) => target.clone(),
                                    None => {
                                        lower_call_pattern(Arc::new(CallPattern::SameArgumentCall))
                                    }
                                },
                                None => lower_call_pattern(Arc::new(CallPattern::SameArgumentCall)),
                            }
                        }
                    }
                } else {
                    {
                        let proof = construct_termination_proof(
                            func_name.clone(),
                            body.clone(),
                            params.clone(),
                            parser_always_advancing.clone(),
                            si.clone(),
                        );
                        let proof_safe_for_branching = match proof.clone() {
                            Some(p) => {
                                if ((p.dimensions.clone().len() as i64) == 0) {
                                    false
                                } else {
                                    {
                                        let mut __all = true;
                                        for dim in p.dimensions.clone().iter().cloned() {
                                            if !(match (*dim.clone()).clone() {
                                                RankingDimension::TreeSize { param: _, .. } => true,
                                                RankingDimension::ListLength {
                                                    param: _, ..
                                                } => true,
                                                _ => false,
                                            }) {
                                                __all = false;
                                                break;
                                            }
                                        }
                                        __all
                                    }
                                }
                            }
                            None => false,
                        };
                        let branching_proof =
                            if ((path_calls.clone() > 1) && !proof_safe_for_branching.clone()) {
                                construct_branching_termination_proof(
                                    func_name.clone(),
                                    body.clone(),
                                    params.clone(),
                                    si.clone(),
                                )
                            } else {
                                None
                            };
                        let branching_proof_safe = match branching_proof.clone() {
                            Some(bp) => {
                                if ((bp.dimensions.clone().len() as i64) == 0) {
                                    false
                                } else {
                                    {
                                        let mut __all = true;
                                        for dim in bp.dimensions.clone().iter().cloned() {
                                            if !(match (*dim.clone()).clone() {
                                                RankingDimension::TreeSize { param: _, .. } => true,
                                                RankingDimension::ListLength {
                                                    param: _, ..
                                                } => true,
                                                _ => false,
                                            }) {
                                                __all = false;
                                                break;
                                            }
                                        }
                                        __all
                                    }
                                }
                            }
                            None => false,
                        };
                        match proof.clone() {
                            Some(p) => {
                                if ((path_calls.clone() == 1) || proof_safe_for_branching.clone()) {
                                    lower_call_pattern(proof_to_call_pattern(p.clone()))
                                } else {
                                    if branching_proof_safe.clone() {
                                        match branching_proof.clone() {
                                            Some(bp) => lower_call_pattern(proof_to_call_pattern(
                                                bp.clone(),
                                            )),
                                            None => lower_call_pattern(Arc::new(
                                                CallPattern::SameArgumentCall,
                                            )),
                                        }
                                    } else {
                                        lower_call_pattern(Arc::new(CallPattern::SameArgumentCall))
                                    }
                                }
                            }
                            None => {
                                if (path_calls.clone() > 1) {
                                    match branching_proof.clone() {
                                        Some(bp) => {
                                            if branching_proof_safe.clone() {
                                                lower_call_pattern(proof_to_call_pattern(
                                                    bp.clone(),
                                                ))
                                            } else {
                                                lower_call_pattern(Arc::new(
                                                    CallPattern::SameArgumentCall,
                                                ))
                                            }
                                        }
                                        None => lower_call_pattern(Arc::new(
                                            CallPattern::SameArgumentCall,
                                        )),
                                    }
                                } else {
                                    lower_call_pattern(Arc::new(CallPattern::SameArgumentCall))
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn bounded_recursive_cost(
    target: Arc<LoweringTarget>,
    per_iter: Arc<CostExpr>,
    func_name: String,
) -> Arc<CostExpr> {
    {
        let p = size_bound_param(target.bound.clone());
        match p.clone() {
            Some(v) => {
                let var = v1_rt::concat("n_".to_string(), v.clone());
                Arc::new(CostExpr::CostSum {
                    binder: var.clone(),
                    upper: Arc::new(SizeExpr::SizeVar { name: var.clone() }),
                    body: simplify_cost(per_iter.clone()),
                })
            }
            None => Arc::new(CostExpr::CostUnknown {
                reason: v1_rt::concat("same-argument recursion in ".to_string(), func_name.clone()),
            }),
        }
    }
}

pub fn bounded_scc_cost(
    target: Arc<LoweringTarget>,
    per_iter: Arc<CostExpr>,
    members: Arc<Vec<String>>,
) -> Arc<CostExpr> {
    {
        let p = size_bound_param(target.bound.clone());
        match p.clone() {
            Some(v) => {
                let var = v1_rt::concat("n_".to_string(), v.clone());
                Arc::new(CostExpr::CostSum {
                    binder: var.clone(),
                    upper: Arc::new(SizeExpr::SizeVar { name: var.clone() }),
                    body: simplify_cost(per_iter.clone()),
                })
            }
            None => Arc::new(CostExpr::CostUnknown {
                reason: v1_rt::concat(
                    "same-argument mutual recursion in ".to_string(),
                    match members.clone().first().cloned() {
                        Some(n) => n.clone(),
                        None => "scc".to_string(),
                    },
                ),
            }),
        }
    }
}

pub fn is_unknown_cost(expr: Arc<CostExpr>) -> bool {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*expr.clone()).clone() {
            CostExpr::CostUnknown { reason: _, .. } => true,
            CostExpr::CostAdd {
                left: l, right: r, ..
            } => (is_unknown_cost(l.clone()) || is_unknown_cost(r.clone())),
            CostExpr::CostMul {
                left: l, right: r, ..
            } => (is_unknown_cost(l.clone()) || is_unknown_cost(r.clone())),
            CostExpr::CostMax {
                left: l, right: r, ..
            } => (is_unknown_cost(l.clone()) || is_unknown_cost(r.clone())),
            CostExpr::CostSum { body: bd, .. } => is_unknown_cost(bd.clone()),
            _ => false,
        }
    })
}

pub fn extract_unknown_reason(mut expr: Arc<CostExpr>) -> String {
    loop {
        match (*expr.clone()).clone() {
            CostExpr::CostUnknown { reason: r, .. } => {
                break r.clone();
            }
            CostExpr::CostAdd {
                left: l, right: r, ..
            } => {
                if is_unknown_cost(l.clone()) {
                    {
                        let __tco_0 = l.clone();
                        expr = __tco_0;
                        continue;
                    }
                } else {
                    {
                        let __tco_0 = r.clone();
                        expr = __tco_0;
                        continue;
                    }
                }
            }
            CostExpr::CostMul {
                left: l, right: r, ..
            } => {
                if is_unknown_cost(l.clone()) {
                    {
                        let __tco_0 = l.clone();
                        expr = __tco_0;
                        continue;
                    }
                } else {
                    {
                        let __tco_0 = r.clone();
                        expr = __tco_0;
                        continue;
                    }
                }
            }
            CostExpr::CostMax {
                left: l, right: r, ..
            } => {
                if is_unknown_cost(l.clone()) {
                    {
                        let __tco_0 = l.clone();
                        expr = __tco_0;
                        continue;
                    }
                } else {
                    {
                        let __tco_0 = r.clone();
                        expr = __tco_0;
                        continue;
                    }
                }
            }
            CostExpr::CostSum { body: bd, .. } => {
                let __tco_0 = bd.clone();
                expr = __tco_0;
                continue;
            }
            _ => {
                break "unknown".to_string();
            }
        }
    }
}

pub fn collect_local_call_edges_in_expr(
    caller: String,
    body: Arc<Node>,
    local_func_set: Arc<HashMap<String, bool>>,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> Arc<Vec<Arc<CallEdge>>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        let this_edges = match (*body.expr_data.clone()).clone() {
            ExprData::ExprCall { .. } => {
                let callee = expr_call_func_at(body.clone(), si.clone());
                if set_has(local_func_set.clone(), callee.clone()) {
                    Arc::new(vec![Arc::new(CallEdge {
                        caller: caller.clone(),
                        callee: callee.clone(),
                    })])
                } else {
                    Arc::new(vec![])
                }
            }
            _ => Arc::new(vec![]),
        };
        let child_edges = Arc::new({
            let mut __result = Vec::new();
            for child in body.children.clone().iter().cloned() {
                __result.extend(
                    (*collect_local_call_edges_in_expr(
                        caller.clone(),
                        child.clone(),
                        local_func_set.clone(),
                        si.clone(),
                    ))
                    .iter()
                    .cloned(),
                );
            }
            __result
        });
        v1_rt::concat(this_edges.clone(), child_edges.clone())
    })
}

pub fn build_call_graph(
    func_entries: Arc<Vec<Arc<FuncEntry>>>,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> Arc<CallGraph> {
    {
        let names = Arc::new({
            let mut __result = Vec::new();
            for entry in func_entries.clone().iter().cloned() {
                __result.push(entry.name.clone());
            }
            __result
        });
        let local_func_set = names.clone().iter().cloned().fold(
            v1_rt::rc_empty_map::<String, bool>(),
            |acc: Arc<HashMap<String, bool>>, name: String| {
                v1_rt::rc_map_insert(acc, name.clone(), true)
            },
        );
        let edges = Arc::new({
            let mut __result = Vec::new();
            for entry in func_entries.clone().iter().cloned() {
                __result.extend(
                    (*collect_local_call_edges_in_expr(
                        entry.name.clone(),
                        entry.body.clone(),
                        local_func_set.clone(),
                        si.clone(),
                    ))
                    .iter()
                    .cloned(),
                );
            }
            __result
        });
        Arc::new(CallGraph {
            edges: Arc::new({
                let mut __result = Vec::new();
                for edge in Arc::new({
                    let mut __result = Vec::new();
                    for edge in edges.clone().iter().cloned() {
                        if (edge.caller.clone() != edge.callee.clone()) {
                            __result.push(edge);
                        }
                    }
                    __result
                })
                .iter()
                .cloned()
                {
                    __result.push(Arc::new(GraphEdge {
                        caller: edge.caller.clone(),
                        callee: edge.callee.clone(),
                    }));
                }
                __result
            }),
        })
    }
}

pub fn scc_label(members: Arc<Vec<String>>) -> String {
    match members.clone().first().cloned() {
        Some(name) => name.clone(),
        None => "scc".to_string(),
    }
}

pub fn classify_scc_call_progress(
    arg_expr: Arc<Node>,
    param_name: String,
    descent_vars: Arc<HashMap<String, bool>>,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> DescentEvidence {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        if is_child_descent_expr(
            arg_expr.clone(),
            param_name.clone(),
            descent_vars.clone(),
            si.clone(),
        ) {
            DescentEvidence::Strict
        } else {
            if is_list_shrink_expr(arg_expr.clone(), param_name.clone(), si.clone()) {
                DescentEvidence::Strict
            } else {
                match (*arg_expr.expr_data.clone()).clone() {
                    ExprData::ExprVar {
                        binding_kind: _, ..
                    } => {
                        let vname = expr_var_name_at(arg_expr.clone(), si.clone());
                        if set_has(descent_vars.clone(), vname.clone()) {
                            DescentEvidence::Strict
                        } else {
                            if (vname.clone() == param_name.clone()) {
                                DescentEvidence::NonIncreasing
                            } else {
                                DescentEvidence::DescentUnknown
                            }
                        }
                    }
                    ExprData::ExprCall { .. } => {
                        if is_tree_size_preserving_wrapper(arg_expr.clone(), si.clone()) {
                            classify_scc_call_progress(
                                wrapper_inner_arg(arg_expr.clone()),
                                param_name.clone(),
                                descent_vars.clone(),
                                si.clone(),
                            )
                        } else {
                            if is_sub_value_extractor(arg_expr.clone(), si.clone()) {
                                {
                                    let inner_progress = classify_scc_call_progress(
                                        extractor_inner_arg(arg_expr.clone()),
                                        param_name.clone(),
                                        descent_vars.clone(),
                                        si.clone(),
                                    );
                                    match inner_progress.clone() {
                                        DescentEvidence::NonIncreasing => DescentEvidence::Strict,
                                        _ => inner_progress.clone(),
                                    }
                                }
                            } else {
                                if is_list_passthrough_call(arg_expr.clone(), si.clone()) {
                                    match list_passthrough_inner_arg(arg_expr.clone(), si.clone()) {
                                        Some(inner) => classify_scc_call_progress(
                                            inner.clone(),
                                            param_name.clone(),
                                            descent_vars.clone(),
                                            si.clone(),
                                        ),
                                        None => DescentEvidence::DescentUnknown,
                                    }
                                } else {
                                    DescentEvidence::DescentUnknown
                                }
                            }
                        }
                    }
                    ExprData::ExprFieldAccess { .. } => {
                        let base = field_access_base(arg_expr.clone());
                        match (*base.expr_data.clone()).clone() {
                            ExprData::ExprVar {
                                binding_kind: _, ..
                            } => {
                                let bname = expr_var_name_at(base.clone(), si.clone());
                                if (set_has(descent_vars.clone(), bname.clone())
                                    || (bname.clone() == param_name.clone()))
                                {
                                    DescentEvidence::Strict
                                } else {
                                    {
                                        let field =
                                            field_access_field_at(arg_expr.clone(), si.clone());
                                        if (field.clone() == param_name.clone()) {
                                            DescentEvidence::NonIncreasing
                                        } else {
                                            DescentEvidence::DescentUnknown
                                        }
                                    }
                                }
                            }
                            _ => DescentEvidence::DescentUnknown,
                        }
                    }
                    ExprData::ExprMethodCall {
                        method_semantics: ms,
                        ..
                    } => {
                        if is_generalized_shrink(arg_expr.clone(), si.clone()) {
                            {
                                let recv = method_receiver(arg_expr.clone());
                                let recv_progress = classify_scc_call_progress(
                                    recv.clone(),
                                    param_name.clone(),
                                    descent_vars.clone(),
                                    si.clone(),
                                );
                                match recv_progress.clone() {
                                    DescentEvidence::Strict => DescentEvidence::Strict,
                                    DescentEvidence::NonIncreasing => DescentEvidence::Strict,
                                    DescentEvidence::DescentUnknown => {
                                        DescentEvidence::DescentUnknown
                                    }
                                }
                            }
                        } else {
                            DescentEvidence::DescentUnknown
                        }
                    }
                    _ => DescentEvidence::DescentUnknown,
                }
            }
        }
    })
}

pub fn collect_scc_child_edges(
    body: Arc<Node>,
    caller: String,
    param_name: String,
    descent_vars: Arc<HashMap<String, bool>>,
    target_set: Arc<HashMap<String, bool>>,
    check_child: bool,
    check_list: bool,
    scc_measure_params: Arc<HashMap<String, Arc<HashMap<String, String>>>>,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> Arc<Vec<Arc<ParserProgressEdge>>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*body.expr_data.clone()).clone() {
            ExprData::ExprLambda => Arc::new(vec![]),
            ExprData::ExprCall { .. } => {
                let callee = expr_call_func_at(body.clone(), si.clone());
                let own_edges = if set_has(target_set.clone(), callee.clone()) {
                    {
                        let callee_params =
                            match v1_rt::map_get(&scc_measure_params, callee.clone()) {
                                Some(p) => p.clone(),
                                None => v1_rt::rc_empty_map::<String, String>(),
                            };
                        let progress = body.children.clone().iter().cloned().fold(
                            DescentEvidence::DescentUnknown,
                            |acc: DescentEvidence, arg_node: Arc<Node>| {
                                let targets_measure =
                                    match arg_name_at(arg_node.clone(), si.clone()) {
                                        Some(aname) => {
                                            (v1_rt::map_get(&callee_params, aname.clone()) != None)
                                        }
                                        None => false,
                                    };
                                if targets_measure.clone() {
                                    {
                                        let arg_progress = classify_scc_call_progress(
                                            arg_value(arg_node.clone()),
                                            param_name.clone(),
                                            descent_vars.clone(),
                                            si.clone(),
                                        );
                                        match arg_progress.clone() {
                                            DescentEvidence::Strict => DescentEvidence::Strict,
                                            DescentEvidence::NonIncreasing => match acc.clone() {
                                                DescentEvidence::Strict => acc.clone(),
                                                _ => DescentEvidence::NonIncreasing,
                                            },
                                            DescentEvidence::DescentUnknown => acc.clone(),
                                        }
                                    }
                                } else {
                                    acc.clone()
                                }
                            },
                        );
                        Arc::new(vec![Arc::new(ParserProgressEdge {
                            caller: caller.clone(),
                            callee: callee.clone(),
                            progress: progress.clone(),
                        })])
                    }
                } else {
                    Arc::new(vec![])
                };
                let child_edges = Arc::new({
                    let mut __result = Vec::new();
                    for child in body.children.clone().iter().cloned() {
                        __result.extend(
                            (*collect_scc_child_edges(
                                child.clone(),
                                caller.clone(),
                                param_name.clone(),
                                descent_vars.clone(),
                                target_set.clone(),
                                check_child.clone(),
                                check_list.clone(),
                                scc_measure_params.clone(),
                                si.clone(),
                            ))
                            .iter()
                            .cloned(),
                        );
                    }
                    __result
                });
                v1_rt::concat(own_edges.clone(), child_edges.clone())
            }
            ExprData::ExprMethodCall {
                method_semantics: ms,
                ..
            } => {
                let receiver = method_receiver(body.clone());
                let is_iter = is_algebra_iteration_method(ms.clone());
                let is_struct = is_structural_children(
                    receiver.clone(),
                    param_name.clone(),
                    descent_vars.clone(),
                    si.clone(),
                );
                if (is_iter.clone() && is_struct.clone()) {
                    {
                        let recv_edges = collect_scc_child_edges(
                            receiver.clone(),
                            caller.clone(),
                            param_name.clone(),
                            descent_vars.clone(),
                            target_set.clone(),
                            check_child.clone(),
                            check_list.clone(),
                            scc_measure_params.clone(),
                            si.clone(),
                        );
                        let args_edges = Arc::new({
                            let mut __result = Vec::new();
                            for arg_node in method_arg_nodes(body.clone()).iter().cloned() {
                                __result.extend(
                                    (*{
                                        let arg_val = arg_value(arg_node.clone());
                                        match (*arg_val.expr_data.clone()).clone() {
                                            ExprData::ExprLambda => match iteration_element_name(
                                                ms.clone(),
                                                arg_val.clone(),
                                                si.clone(),
                                            ) {
                                                Some(iter_name) => {
                                                    let ext_vars = v1_rt::rc_map_insert(
                                                        descent_vars.clone(),
                                                        iter_name.clone(),
                                                        true,
                                                    );
                                                    collect_scc_child_edges(
                                                        lambda_body(arg_val.clone()),
                                                        caller.clone(),
                                                        param_name.clone(),
                                                        ext_vars.clone(),
                                                        target_set.clone(),
                                                        check_child.clone(),
                                                        check_list.clone(),
                                                        scc_measure_params.clone(),
                                                        si.clone(),
                                                    )
                                                }
                                                None => Arc::new(vec![]),
                                            },
                                            _ => collect_scc_child_edges(
                                                arg_val.clone(),
                                                caller.clone(),
                                                param_name.clone(),
                                                descent_vars.clone(),
                                                target_set.clone(),
                                                check_child.clone(),
                                                check_list.clone(),
                                                scc_measure_params.clone(),
                                                si.clone(),
                                            ),
                                        }
                                    })
                                    .iter()
                                    .cloned(),
                                );
                            }
                            __result
                        });
                        v1_rt::concat(recv_edges.clone(), args_edges.clone())
                    }
                } else {
                    Arc::new({
                        let mut __result = Vec::new();
                        for child in body.children.clone().iter().cloned() {
                            __result.extend(
                                (*collect_scc_child_edges(
                                    child.clone(),
                                    caller.clone(),
                                    param_name.clone(),
                                    descent_vars.clone(),
                                    target_set.clone(),
                                    check_child.clone(),
                                    check_list.clone(),
                                    scc_measure_params.clone(),
                                    si.clone(),
                                ))
                                .iter()
                                .cloned(),
                            );
                        }
                        __result
                    })
                }
            }
            ExprData::ExprLet => {
                let val = let_value(body.clone());
                let val_edges = collect_scc_child_edges(
                    val.clone(),
                    caller.clone(),
                    param_name.clone(),
                    descent_vars.clone(),
                    target_set.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    scc_measure_params.clone(),
                    si.clone(),
                );
                let is_direct = ((check_child.clone()
                    && is_child_descent_expr(
                        val.clone(),
                        param_name.clone(),
                        descent_vars.clone(),
                        si.clone(),
                    ))
                    || (check_list.clone()
                        && is_list_shrink_expr(val.clone(), param_name.clone(), si.clone())));
                let is_var = match (*val.expr_data.clone()).clone() {
                    ExprData::ExprVar {
                        binding_kind: _, ..
                    } => set_has(
                        descent_vars.clone(),
                        expr_var_name_at(val.clone(), si.clone()),
                    ),
                    _ => false,
                };
                let is_option = is_if_option_descent(
                    val.clone(),
                    param_name.clone(),
                    descent_vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    si.clone(),
                );
                let is_match_descent = is_match_option_descent(
                    val.clone(),
                    param_name.clone(),
                    descent_vars.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    si.clone(),
                );
                let is_wrapped = if is_tree_size_preserving_wrapper(val.clone(), si.clone()) {
                    {
                        let inner = wrapper_inner_arg(val.clone());
                        let inner_d = ((check_child.clone()
                            && is_child_descent_expr(
                                inner.clone(),
                                param_name.clone(),
                                descent_vars.clone(),
                                si.clone(),
                            ))
                            || (check_list.clone()
                                && is_list_shrink_expr(
                                    inner.clone(),
                                    param_name.clone(),
                                    si.clone(),
                                )));
                        let inner_v = match (*inner.expr_data.clone()).clone() {
                            ExprData::ExprVar {
                                binding_kind: _, ..
                            } => set_has(
                                descent_vars.clone(),
                                expr_var_name_at(inner.clone(), si.clone()),
                            ),
                            _ => false,
                        };
                        (inner_d.clone() || inner_v.clone())
                    }
                } else {
                    false
                };
                let is_extraction = if is_sub_value_extractor(val.clone(), si.clone()) {
                    {
                        let inner = extractor_inner_arg(val.clone());
                        let inner_d = ((check_child.clone()
                            && is_child_descent_expr(
                                inner.clone(),
                                param_name.clone(),
                                descent_vars.clone(),
                                si.clone(),
                            ))
                            || (check_list.clone()
                                && is_list_shrink_expr(
                                    inner.clone(),
                                    param_name.clone(),
                                    si.clone(),
                                )));
                        let inner_v = match (*inner.expr_data.clone()).clone() {
                            ExprData::ExprVar {
                                binding_kind: _, ..
                            } => set_has(
                                descent_vars.clone(),
                                expr_var_name_at(inner.clone(), si.clone()),
                            ),
                            _ => false,
                        };
                        let inner_p = match (*inner.expr_data.clone()).clone() {
                            ExprData::ExprVar {
                                binding_kind: _, ..
                            } => {
                                (expr_var_name_at(inner.clone(), si.clone()) == param_name.clone())
                            }
                            _ => false,
                        };
                        ((inner_d.clone() || inner_v.clone()) || inner_p.clone())
                    }
                } else {
                    false
                };
                let is_children_list = match (*val.expr_data.clone()).clone() {
                    ExprData::ExprFieldAccess { .. } => {
                        let base = field_access_base(val.clone());
                        let field = field_access_field_at(val.clone(), si.clone());
                        (is_children_list_field(field.clone())
                            && match (*base.expr_data.clone()).clone() {
                                ExprData::ExprVar {
                                    binding_kind: _, ..
                                } => {
                                    let bname = expr_var_name_at(base.clone(), si.clone());
                                    ((bname.clone() == param_name.clone())
                                        || set_has(descent_vars.clone(), bname.clone()))
                                }
                                _ => false,
                            })
                    }
                    _ => false,
                };
                let is_passthrough = if is_list_passthrough_call(val.clone(), si.clone()) {
                    match list_passthrough_inner_arg(val.clone(), si.clone()) {
                        Some(inner) => {
                            (((check_child.clone()
                                && is_child_descent_expr(
                                    inner.clone(),
                                    param_name.clone(),
                                    descent_vars.clone(),
                                    si.clone(),
                                ))
                                || (check_list.clone()
                                    && is_list_shrink_expr(
                                        inner.clone(),
                                        param_name.clone(),
                                        si.clone(),
                                    )))
                                || match (*inner.expr_data.clone()).clone() {
                                    ExprData::ExprVar {
                                        binding_kind: _, ..
                                    } => set_has(
                                        descent_vars.clone(),
                                        expr_var_name_at(inner.clone(), si.clone()),
                                    ),
                                    _ => false,
                                })
                        }
                        None => false,
                    }
                } else {
                    false
                };
                let is_consuming_helper = (check_list.clone()
                    && is_tokens_consuming_call(
                        val.clone(),
                        param_name.clone(),
                        descent_vars.clone(),
                        si.clone(),
                    ));
                let next_vars = if ((((((((is_direct.clone() || is_var.clone())
                    || is_option.clone())
                    || is_match_descent.clone())
                    || is_wrapped.clone())
                    || is_extraction.clone())
                    || is_children_list.clone())
                    || is_passthrough.clone())
                    || is_consuming_helper.clone())
                {
                    v1_rt::rc_map_insert(
                        descent_vars.clone(),
                        let_binding_name_at(body.clone(), si.clone()),
                        true,
                    )
                } else {
                    descent_vars.clone()
                };
                let body_edges = match let_body(body.clone()) {
                    Some(b) => collect_scc_child_edges(
                        b.clone(),
                        caller.clone(),
                        param_name.clone(),
                        next_vars.clone(),
                        target_set.clone(),
                        check_child.clone(),
                        check_list.clone(),
                        scc_measure_params.clone(),
                        si.clone(),
                    ),
                    None => Arc::new(vec![]),
                };
                v1_rt::concat(val_edges.clone(), body_edges.clone())
            }
            ExprData::ExprMatch => {
                let scrut = match_scrutinee(body.clone());
                let scrut_edges = collect_scc_child_edges(
                    scrut.clone(),
                    caller.clone(),
                    param_name.clone(),
                    descent_vars.clone(),
                    target_set.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    scc_measure_params.clone(),
                    si.clone(),
                );
                let arms_edges = Arc::new({
                    let mut __result = Vec::new();
                    for arm_node in match_arm_nodes(body.clone()).iter().cloned() {
                        __result.extend(
                            (*collect_scc_child_edges(
                                arm_body(arm_node.clone()),
                                caller.clone(),
                                param_name.clone(),
                                descent_vars.clone(),
                                target_set.clone(),
                                check_child.clone(),
                                check_list.clone(),
                                scc_measure_params.clone(),
                                si.clone(),
                            ))
                            .iter()
                            .cloned(),
                        );
                    }
                    __result
                });
                v1_rt::concat(scrut_edges.clone(), arms_edges.clone())
            }
            ExprData::ExprBlock => {
                let result = body.children.clone().iter().cloned().fold(
                    Arc::new(SccEdgeBlockAcc {
                        edges: Arc::new(vec![]),
                        vars: descent_vars.clone(),
                    }),
                    |acc: Arc<SccEdgeBlockAcc>, stmt: Arc<Node>| {
                        let stmt_edges = collect_scc_child_edges(
                            stmt.clone(),
                            caller.clone(),
                            param_name.clone(),
                            acc.vars.clone(),
                            target_set.clone(),
                            check_child.clone(),
                            check_list.clone(),
                            scc_measure_params.clone(),
                            si.clone(),
                        );
                        let next_vars = collect_descent_vars(
                            stmt.clone(),
                            param_name.clone(),
                            acc.vars.clone(),
                            check_child.clone(),
                            check_list.clone(),
                            si.clone(),
                        );
                        Arc::new(SccEdgeBlockAcc {
                            edges: v1_rt::concat(acc.edges.clone(), stmt_edges.clone()),
                            vars: next_vars.clone(),
                        })
                    },
                );
                result.edges.clone()
            }
            ExprData::ExprIf => {
                let cond_edges = collect_scc_child_edges(
                    if_condition(body.clone()),
                    caller.clone(),
                    param_name.clone(),
                    descent_vars.clone(),
                    target_set.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    scc_measure_params.clone(),
                    si.clone(),
                );
                let then_branch = if_then_branch(body.clone());
                let else_opt = if_else_branch(body.clone());
                let then_edges = collect_scc_child_edges(
                    then_branch.clone(),
                    caller.clone(),
                    param_name.clone(),
                    descent_vars.clone(),
                    target_set.clone(),
                    check_child.clone(),
                    check_list.clone(),
                    scc_measure_params.clone(),
                    si.clone(),
                );
                let else_edges = match else_opt.clone() {
                    Some(eb) => collect_scc_child_edges(
                        eb.clone(),
                        caller.clone(),
                        param_name.clone(),
                        descent_vars.clone(),
                        target_set.clone(),
                        check_child.clone(),
                        check_list.clone(),
                        scc_measure_params.clone(),
                        si.clone(),
                    ),
                    None => Arc::new(vec![]),
                };
                v1_rt::concat(
                    cond_edges.clone(),
                    v1_rt::concat(then_edges.clone(), else_edges.clone()),
                )
            }
            _ => Arc::new({
                let mut __result = Vec::new();
                for child in body.children.clone().iter().cloned() {
                    __result.extend(
                        (*collect_scc_child_edges(
                            child.clone(),
                            caller.clone(),
                            param_name.clone(),
                            descent_vars.clone(),
                            target_set.clone(),
                            check_child.clone(),
                            check_list.clone(),
                            scc_measure_params.clone(),
                            si.clone(),
                        ))
                        .iter()
                        .cloned(),
                    );
                }
                __result
            }),
        }
    })
}

pub fn is_scc_container_child_descent(
    members: Arc<Vec<String>>,
    func_index: Arc<HashMap<String, Arc<FuncEntry>>>,
    scc_name_set: Arc<HashMap<String, bool>>,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> bool {
    {
        let measure_params =
            build_scc_measure_params(members.clone(), func_index.clone(), si.clone());
        let edges = Arc::new({
            let mut __result = Vec::new();
            for name in members.clone().iter().cloned() {
                __result.extend(
                    (*match v1_rt::map_get(&func_index, name.clone()) {
                        Some(entry) => {
                            let best_edges = entry.params.clone().iter().cloned().fold(
                                Arc::new(vec![]),
                                |best: _, p: Arc<Node>| {
                                    let pname = param_node_name_at(p.clone(), si.clone());
                                    let descent_vars = collect_descent_vars(
                                        entry.body.clone(),
                                        pname.clone(),
                                        v1_rt::rc_empty_map::<String, bool>(),
                                        true,
                                        true,
                                        si.clone(),
                                    );
                                    let param_edges = collect_scc_child_edges(
                                        entry.body.clone(),
                                        name.clone(),
                                        pname.clone(),
                                        descent_vars.clone(),
                                        scc_name_set.clone(),
                                        true,
                                        true,
                                        measure_params.clone(),
                                        si.clone(),
                                    );
                                    let unknown_count =
                                        count_unknown_progress_edges(param_edges.clone());
                                    let best_unknown = count_unknown_progress_edges(best.clone());
                                    if (((best.clone().len() as i64) == 0)
                                        || (unknown_count.clone() < best_unknown.clone()))
                                    {
                                        param_edges.clone()
                                    } else {
                                        best.clone()
                                    }
                                },
                            );
                            best_edges.clone()
                        }
                        None => Arc::new(vec![]),
                    })
                    .iter()
                    .cloned(),
                );
            }
            __result
        });
        let unknown_edge_count = count_unknown_progress_edges(edges.clone());
        (((unknown_edge_count.clone() == 0) && ((edges.clone().len() as i64) > 0))
            && (same_progress_subgraph_has_cycle(members.clone(), edges.clone()) == false))
    }
}

pub fn progress_edge_to_proof_edge(pe: Arc<ParserProgressEdge>) -> Arc<ProofEdge> {
    Arc::new(ProofEdge {
        caller: pe.caller.clone(),
        callee: pe.callee.clone(),
        evidence: Arc::new(vec![pe.progress.clone()]),
    })
}

pub fn count_unknown_progress_edges(edges: Arc<Vec<Arc<ParserProgressEdge>>>) -> i64 {
    (Arc::new({
        let mut __result = Vec::new();
        for e in edges.clone().iter().cloned() {
            if (e.progress.clone() == DescentEvidence::DescentUnknown) {
                __result.push(e);
            }
        }
        __result
    })
    .len() as i64)
}

pub fn count_unknown_proof_edges(edges: Arc<Vec<Arc<ProofEdge>>>) -> i64 {
    (Arc::new({
        let mut __result = Vec::new();
        for e in edges.clone().iter().cloned() {
            if match e.evidence.clone().first().cloned() {
                Some(DescentEvidence::DescentUnknown) => true,
                _ => false,
            } {
                __result.push(e);
            }
        }
        __result
    })
    .len() as i64)
}

