pub fn cost_expr_degree_note() -> String {
    thread_local! {
        static CACHED: String = {
            "Asymptotic reading (space-complexity increment 2): the polynomial degree of a CostExpr. A CostSum over a size variable is one factor of n (+1 degree); sequential/parallel take the MAX degree; products ADD degrees; a bare log is below linear (degree 0 for the polynomial reading). Absent = the frontier (CostExtern/CostUnknown) — fail-closed, never a fabricated degree. Applied to space_of(work) it yields the SPACE order, which is <= the TIME order by construction (space_of collapses the CostSum that a reducing fold's TIME carries): the headline O(n)-time / O(1)-space, decided asymptotically.".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn cost_expr_degree(e: Arc<CostExpr>) -> Option<i64> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || match (*e.clone()).clone() {
        CostExpr::CostConst { value: _, .. } => Some(0),
        CostExpr::CostAdd {
            left: l, right: r, ..
        } => match cost_expr_degree(l.clone()) {
            Some(ld) => match cost_expr_degree(r.clone()) {
                Some(rd) => Some(if (ld.clone() >= rd.clone()) {
                    ld.clone()
                } else {
                    rd.clone()
                }),
                None => None,
            },
            None => None,
        },
        CostExpr::CostMax {
            left: l, right: r, ..
        } => match cost_expr_degree(l.clone()) {
            Some(ld) => match cost_expr_degree(r.clone()) {
                Some(rd) => Some(if (ld.clone() >= rd.clone()) {
                    ld.clone()
                } else {
                    rd.clone()
                }),
                None => None,
            },
            None => None,
        },
        CostExpr::CostMul {
            left: l, right: r, ..
        } => match cost_expr_degree(l.clone()) {
            Some(ld) => match cost_expr_degree(r.clone()) {
                Some(rd) => Some((ld.clone() + rd.clone())),
                None => None,
            },
            None => None,
        },
        CostExpr::CostSum { body: bd, .. } => match cost_expr_degree(bd.clone()) {
            Some(bdeg) => Some((1 + bdeg.clone())),
            None => None,
        },
        CostExpr::CostLog { .. } => Some(0),
        CostExpr::CostExtern { name: _, .. } => None,
        CostExpr::CostUnknown { reason: _, .. } => None,
    })
}

pub fn degree_to_bound(degree: i64, param: String) -> Arc<CostBound> {
    if (degree.clone() == 0) {
        cost_constant()
    } else {
        cost_poly(param.clone(), degree.clone())
    }
}

pub fn space_asymptotic_bound(work: Arc<CostExpr>, param: String) -> Arc<CostBound> {
    match cost_expr_degree(space_of(work.clone())) {
        Some(d) => degree_to_bound(d.clone(), param.clone()),
        None => Arc::new(CostBound::ForeverBound),
    }
}

pub fn time_asymptotic_bound(work: Arc<CostExpr>, param: String) -> Arc<CostBound> {
    match cost_expr_degree(work.clone()) {
        Some(d) => degree_to_bound(d.clone(), param.clone()),
        None => Arc::new(CostBound::ForeverBound),
    }
}

pub fn eval_size_expr_concrete(s: Arc<SizeExpr>, env: Arc<HashMap<String, i64>>) -> Option<i64> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || match (*s.clone()).clone() {
        SizeExpr::SizeConst { value: v, .. } => Some(v.clone()),
        SizeExpr::SizeVar { name: n, .. } => v1_rt::map_get(&env, n.clone()),
        SizeExpr::SizeLen { collection: c, .. } => v1_rt::map_get(&env, c.clone()),
        SizeExpr::SizeAdd {
            left: l, right: r, ..
        } => match eval_size_expr_concrete(l.clone(), env.clone()) {
            Some(lv) => match eval_size_expr_concrete(r.clone(), env.clone()) {
                Some(rv) => Some((lv.clone() + rv.clone())),
                None => None,
            },
            None => None,
        },
        SizeExpr::SizeMax {
            left: l, right: r, ..
        } => match eval_size_expr_concrete(l.clone(), env.clone()) {
            Some(lv) => match eval_size_expr_concrete(r.clone(), env.clone()) {
                Some(rv) => Some(if (lv.clone() >= rv.clone()) {
                    lv.clone()
                } else {
                    rv.clone()
                }),
                None => None,
            },
            None => None,
        },
    })
}

pub fn int_max2(a: i64, b: i64) -> i64 {
    if (a.clone() >= b.clone()) {
        a.clone()
    } else {
        b.clone()
    }
}

pub fn eval_cost_expr_concrete(e: Arc<CostExpr>, env: Arc<HashMap<String, i64>>) -> Option<i64> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || match (*e.clone()).clone() {
        CostExpr::CostConst { value: v, .. } => Some(v.clone()),
        CostExpr::CostAdd {
            left: l, right: r, ..
        } => match eval_cost_expr_concrete(l.clone(), env.clone()) {
            Some(lv) => match eval_cost_expr_concrete(r.clone(), env.clone()) {
                Some(rv) => Some((lv.clone() + rv.clone())),
                None => None,
            },
            None => None,
        },
        CostExpr::CostMul {
            left: l, right: r, ..
        } => match eval_cost_expr_concrete(l.clone(), env.clone()) {
            Some(lv) => match eval_cost_expr_concrete(r.clone(), env.clone()) {
                Some(rv) => Some((lv.clone() * rv.clone())),
                None => None,
            },
            None => None,
        },
        CostExpr::CostMax {
            left: l, right: r, ..
        } => match eval_cost_expr_concrete(l.clone(), env.clone()) {
            Some(lv) => match eval_cost_expr_concrete(r.clone(), env.clone()) {
                Some(rv) => Some(int_max2(lv.clone(), rv.clone())),
                None => None,
            },
            None => None,
        },
        CostExpr::CostSum {
            upper: up,
            body: bd,
            ..
        } => match eval_size_expr_concrete(up.clone(), env.clone()) {
            Some(n) => match eval_cost_expr_concrete(bd.clone(), env.clone()) {
                Some(bv) => Some((n.clone() * bv.clone())),
                None => None,
            },
            None => None,
        },
        CostExpr::CostLog { .. } => None,
        CostExpr::CostExtern { name: _, .. } => None,
        CostExpr::CostUnknown { reason: _, .. } => None,
    })
}

pub fn collection_output(
    binder: String,
    size: Arc<SizeExpr>,
) -> Arc<HashMap<String, Arc<CostExpr>>> {
    {
        let result = seed_cost_map(
            "result".to_string(),
            cost_loop(
                binder.clone(),
                size.clone(),
                Arc::new(CostExpr::CostConst { value: 1 }),
            ),
        );
        result
    }
}

pub fn scalar_output() -> Arc<HashMap<String, Arc<CostExpr>>> {
    v1_rt::rc_empty_map::<String, Arc<CostExpr>>()
}

pub fn method_preserves_collection_size(method_semantics: Option<Arc<MethodSemantics>>) -> bool {
    if (method_semantics.clone() == None) {
        false
    } else {
        match (*method_semantics.clone().unwrap()).clone() {
            MethodSemantics::AlgebraMethodSemantics {
                size_effect: se, ..
            } => match se.clone() {
                Some(CollectionSizeEffect::ShrinkEffect) => true,
                Some(CollectionSizeEffect::IdentityEffect) => true,
                _ => false,
            },
            _ => false,
        }
    }
}

pub fn receiver_size_var(
    mut recv: Arc<Node>,
    mut si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> Arc<SizeExpr> {
    loop {
        match (*recv.expr_data.clone()).clone() {
            ExprData::ExprVar { .. } => {
                break Arc::new(SizeExpr::SizeLen {
                    collection: expr_var_name_at(recv.clone(), si.clone()),
                });
            }
            ExprData::ExprFieldAccess { .. } => {
                break Arc::new(SizeExpr::SizeLen {
                    collection: field_access_field_at(recv.clone(), si.clone()),
                });
            }
            ExprData::ExprMethodCall {
                method_semantics: method_semantics,
                ..
            } => {
                let inner_recv = match recv.children.clone().first().cloned() {
                    Some(r) => r.clone(),
                    None => recv.clone(),
                };
                if method_preserves_collection_size(method_semantics.clone()) {
                    {
                        let __tco_0 = inner_recv.clone();
                        recv = __tco_0;
                        continue;
                    }
                } else {
                    break Arc::new(SizeExpr::SizeLen {
                        collection: "__expr".to_string(),
                    });
                }
            }
            _ => {
                break Arc::new(SizeExpr::SizeLen {
                    collection: "__expr".to_string(),
                });
            }
        }
    }
}

pub fn size_binder_name(size: Arc<SizeExpr>) -> String {
    match (*size.clone()).clone() {
        SizeExpr::SizeLen { collection: c, .. } => v1_rt::concat("_".to_string(), c.clone()),
        SizeExpr::SizeVar { name: n, .. } => n.clone(),
        _ => "_i".to_string(),
    }
}

pub fn resolve_lambda_arg(
    mc_arg_nodes: Arc<Vec<Arc<Node>>>,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> Option<Arc<Node>> {
    {
        let f_arg = Arc::new({
            let mut __result = Vec::new();
            for a in mc_arg_nodes.clone().iter().cloned() {
                if (authored_name_at(si.clone(), a.clone()) == "f".to_string()) {
                    __result.push(a);
                }
            }
            __result
        })
        .first()
        .cloned();
        match f_arg.clone() {
            Some(fa) => Some(arg_value(fa.clone())),
            None => Arc::new({
                let mut __result = Vec::new();
                for a in mc_arg_nodes.clone().iter().cloned() {
                    __result.push(arg_value(a.clone()));
                }
                __result
            })
            .first()
            .cloned(),
        }
    }
}

pub fn resolve_callback_cost(
    lambda_arg: Option<Arc<Node>>,
    recv_r: Arc<SummaryResult>,
    func_index: Arc<HashMap<String, Arc<FuncEntry>>>,
    scc_index: Arc<HashMap<String, Arc<SccInfo>>>,
    parser_always_advancing: Arc<HashMap<String, bool>>,
    recursion_ctx: RecursionContext,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> Arc<SummaryResult> {
    match lambda_arg.clone() {
        Some(la) => match (*la.expr_data.clone()).clone() {
            ExprData::ExprVar { .. } => {
                let fn_ref = expr_var_name_at(la.clone(), si.clone());
                match v1_rt::map_get(&func_index, fn_ref.clone()) {
                    Some(_) => get_or_compute_summary(
                        fn_ref.clone(),
                        func_index.clone(),
                        scc_index.clone(),
                        recv_r.table.clone(),
                        parser_always_advancing.clone(),
                        recursion_ctx.clone(),
                        si.clone(),
                    ),
                    None => cost_of_expr(
                        la.clone(),
                        func_index.clone(),
                        scc_index.clone(),
                        recv_r.table.clone(),
                        parser_always_advancing.clone(),
                        recursion_ctx.clone(),
                        si.clone(),
                    ),
                }
            }
            _ => cost_of_expr(
                la.clone(),
                func_index.clone(),
                scc_index.clone(),
                recv_r.table.clone(),
                parser_always_advancing.clone(),
                recursion_ctx.clone(),
                si.clone(),
            ),
        },
        None => Arc::new(SummaryResult {
            summary: Arc::new(ComplexitySummary {
                work: Arc::new(CostExpr::CostConst { value: 1 }),
                span: Arc::new(CostExpr::CostConst { value: 1 }),
                output_size: v1_rt::rc_empty_map::<String, Arc<CostExpr>>(),
                certainty: Certainty::Conservative,
                peak_space: None,
            }),
            table: recv_r.table.clone(),
        }),
    }
}

pub fn cost_of_method_by_shape(
    shape: CostShape,
    produces_collection: bool,
    recv_r: Arc<SummaryResult>,
    mc_args: Arc<Vec<Arc<Node>>>,
    size: Arc<SizeExpr>,
    binder: String,
    func_index: Arc<HashMap<String, Arc<FuncEntry>>>,
    scc_index: Arc<HashMap<String, Arc<SccInfo>>>,
    parser_always_advancing: Arc<HashMap<String, bool>>,
    recursion_ctx: RecursionContext,
    si: Arc<HashMap<String, Arc<NewlineIndex>>>,
) -> Arc<SummaryResult> {
    match shape.clone() {
        CostShape::ShapeIterateBody => {
            let lambda_arg = resolve_lambda_arg(mc_args.clone(), si.clone());
            let body_result = resolve_callback_cost(
                lambda_arg.clone(),
                recv_r.clone(),
                func_index.clone(),
                scc_index.clone(),
                parser_always_advancing.clone(),
                recursion_ctx.clone(),
                si.clone(),
            );
            let loop_work = cost_loop(
                binder.clone(),
                size.clone(),
                body_result.summary.clone().work.clone(),
            );
            let os = if (produces_collection.clone() == false) {
                body_result.summary.clone().output_size.clone()
            } else {
                {
                    let r = seed_cost_map(
                        "result".to_string(),
                        cost_loop(
                            binder.clone(),
                            size.clone(),
                            Arc::new(CostExpr::CostConst { value: 1 }),
                        ),
                    );
                    r.clone()
                }
            };
            Arc::new(SummaryResult {
                summary: Arc::new(ComplexitySummary {
                    work: cost_seq(recv_r.summary.clone().work.clone(), loop_work.clone()),
                    span: cost_seq(recv_r.summary.clone().span.clone(), loop_work.clone()),
                    output_size: os.clone(),
                    certainty: body_result.summary.clone().certainty.clone(),
                    peak_space: None,
                }),
                table: body_result.table.clone(),
            })
        }
        CostShape::ShapeSortBody => {
            let lambda_arg = resolve_lambda_arg(mc_args.clone(), si.clone());
            let key_result = match lambda_arg.clone() {
                Some(la) => cost_of_expr(
                    la.clone(),
                    func_index.clone(),
                    scc_index.clone(),
                    recv_r.table.clone(),
                    parser_always_advancing.clone(),
                    recursion_ctx.clone(),
                    si.clone(),
                ),
                None => Arc::new(SummaryResult {
                    summary: Arc::new(ComplexitySummary {
                        work: Arc::new(CostExpr::CostConst { value: 1 }),
                        span: Arc::new(CostExpr::CostConst { value: 1 }),
                        output_size: v1_rt::rc_empty_map::<String, Arc<CostExpr>>(),
                        certainty: Certainty::Proven,
                        peak_space: None,
                    }),
                    table: recv_r.table.clone(),
                }),
            };
            let log_factor = Arc::new(CostExpr::CostLog {
                base: 2,
                argument: size.clone(),
            });
            let per_comparison = key_result.summary.clone().work.clone();
            let sort_work = Arc::new(CostExpr::CostMul {
                left: cost_loop(binder.clone(), size.clone(), per_comparison.clone()),
                right: log_factor.clone(),
            });
            let sort_os = seed_cost_map(
                "result".to_string(),
                cost_loop(
                    binder.clone(),
                    size.clone(),
                    Arc::new(CostExpr::CostConst { value: 1 }),
                ),
            );
            Arc::new(SummaryResult {
                summary: Arc::new(ComplexitySummary {
                    work: cost_seq(recv_r.summary.clone().work.clone(), sort_work.clone()),
                    span: cost_seq(recv_r.summary.clone().span.clone(), sort_work.clone()),
                    output_size: sort_os.clone(),
                    certainty: key_result.summary.clone().certainty.clone(),
                    peak_space: None,
                }),
                table: key_result.table.clone(),
            })
        }
        CostShape::ShapeLinearScan => {
            let loop_work = cost_loop(
                binder.clone(),
                size.clone(),
                Arc::new(CostExpr::CostConst { value: 1 }),
            );
            let scan_os = if produces_collection.clone() {
                seed_cost_map(
                    "result".to_string(),
                    cost_loop(
                        binder.clone(),
                        size.clone(),
                        Arc::new(CostExpr::CostConst { value: 1 }),
                    ),
                )
            } else {
                v1_rt::rc_empty_map::<String, Arc<CostExpr>>()
            };
            Arc::new(SummaryResult {
                summary: Arc::new(ComplexitySummary {
                    work: cost_seq(recv_r.summary.clone().work.clone(), loop_work.clone()),
                    span: cost_seq(recv_r.summary.clone().span.clone(), loop_work.clone()),
                    output_size: scan_os.clone(),
                    certainty: recv_r.summary.clone().certainty.clone(),
                    peak_space: None,
                }),
                table: recv_r.table.clone(),
            })
        }
        CostShape::ShapeConstant => Arc::new(SummaryResult {
            summary: Arc::new(ComplexitySummary {
                work: cost_seq(
                    recv_r.summary.clone().work.clone(),
                    Arc::new(CostExpr::CostConst { value: 1 }),
                ),
                span: cost_seq(
                    recv_r.summary.clone().span.clone(),
                    Arc::new(CostExpr::CostConst { value: 1 }),
                ),
                output_size: v1_rt::rc_empty_map::<String, Arc<CostExpr>>(),
                certainty: recv_r.summary.clone().certainty.clone(),
                peak_space: None,
            }),
            table: recv_r.table.clone(),
        }),
    }
}

