pub fn simplify_cost(expr: Arc<CostExpr>) -> Arc<CostExpr> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*expr.clone()).clone() {
            CostExpr::CostConst { value: _, .. } => expr.clone(),
            CostExpr::CostAdd {
                left: l, right: r, ..
            } => {
                let sl = simplify_cost(l.clone());
                let sr = simplify_cost(r.clone());
                let simplified = match (*sl.clone()).clone() {
                    CostExpr::CostConst { value: 0, .. } => sr.clone(),
                    CostExpr::CostConst { value: a, .. } => match (*sr.clone()).clone() {
                        CostExpr::CostConst { value: 0, .. } => sl.clone(),
                        CostExpr::CostConst { value: b, .. } => Arc::new(CostExpr::CostConst {
                            value: (a.clone() + b.clone()),
                        }),
                        _ => Arc::new(CostExpr::CostAdd {
                            left: sl.clone(),
                            right: sr.clone(),
                        }),
                    },
                    _ => match (*sr.clone()).clone() {
                        CostExpr::CostConst { value: 0, .. } => sl.clone(),
                        _ => Arc::new(CostExpr::CostAdd {
                            left: sl.clone(),
                            right: sr.clone(),
                        }),
                    },
                };
                simplified
            }
            CostExpr::CostMul {
                left: l, right: r, ..
            } => {
                let sl = simplify_cost(l.clone());
                let sr = simplify_cost(r.clone());
                let simplified = match (*sl.clone()).clone() {
                    CostExpr::CostConst { value: 0, .. } => {
                        Arc::new(CostExpr::CostConst { value: 0 })
                    }
                    CostExpr::CostConst { value: 1, .. } => sr.clone(),
                    _ => match (*sr.clone()).clone() {
                        CostExpr::CostConst { value: 0, .. } => {
                            Arc::new(CostExpr::CostConst { value: 0 })
                        }
                        CostExpr::CostConst { value: 1, .. } => sl.clone(),
                        _ => Arc::new(CostExpr::CostMul {
                            left: sl.clone(),
                            right: sr.clone(),
                        }),
                    },
                };
                simplified
            }
            CostExpr::CostMax {
                left: l, right: r, ..
            } => {
                let sl = simplify_cost(l.clone());
                let sr = simplify_cost(r.clone());
                let simplified = match (*sl.clone()).clone() {
                    CostExpr::CostConst { value: 0, .. } => sr.clone(),
                    CostExpr::CostConst { value: a, .. } => match (*sr.clone()).clone() {
                        CostExpr::CostConst { value: 0, .. } => sl.clone(),
                        CostExpr::CostConst { value: b, .. } => {
                            if (a.clone() > b.clone()) {
                                sl.clone()
                            } else {
                                sr.clone()
                            }
                        }
                        _ => Arc::new(CostExpr::CostMax {
                            left: sl.clone(),
                            right: sr.clone(),
                        }),
                    },
                    _ => match (*sr.clone()).clone() {
                        CostExpr::CostConst { value: 0, .. } => sl.clone(),
                        _ => Arc::new(CostExpr::CostMax {
                            left: sl.clone(),
                            right: sr.clone(),
                        }),
                    },
                };
                simplified
            }
            CostExpr::CostSum {
                binder: b,
                upper: u,
                body: bd,
                ..
            } => {
                let sbd = simplify_cost(bd.clone());
                match (*sbd.clone()).clone() {
                    CostExpr::CostConst { value: 0, .. } => {
                        Arc::new(CostExpr::CostConst { value: 0 })
                    }
                    _ => Arc::new(CostExpr::CostSum {
                        binder: b.clone(),
                        upper: u.clone(),
                        body: sbd.clone(),
                    }),
                }
            }
            CostExpr::CostLog {
                base: b,
                argument: a,
                ..
            } => Arc::new(CostExpr::CostLog {
                base: b.clone(),
                argument: a.clone(),
            }),
            CostExpr::CostExtern { name: _, .. } => expr.clone(),
            CostExpr::CostUnknown { reason: _, .. } => expr.clone(),
        }
    })
}

pub fn format_size(size: Arc<SizeExpr>) -> String {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*size.clone()).clone() {
            SizeExpr::SizeLen { collection: c, .. } => {
                v1_rt::concat(v1_rt::concat("|".to_string(), c.clone()), "|".to_string())
            }
            SizeExpr::SizeVar { name: n, .. } => n.clone(),
            SizeExpr::SizeConst { value: v, .. } => (v.clone()).to_string(),
            SizeExpr::SizeAdd {
                left: l, right: r, ..
            } => v1_rt::concat(
                v1_rt::concat(format_size(l.clone()), " + ".to_string()),
                format_size(r.clone()),
            ),
            SizeExpr::SizeMax {
                left: l, right: r, ..
            } => v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat("max(".to_string(), format_size(l.clone())),
                        ", ".to_string(),
                    ),
                    format_size(r.clone()),
                ),
                ")".to_string(),
            ),
        }
    })
}

pub fn normalize_asymptotic(expr: Arc<CostExpr>) -> Arc<CostExpr> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*expr.clone()).clone() {
            CostExpr::CostConst { value: v, .. } => {
                if (v.clone() <= 0) {
                    Arc::new(CostExpr::CostConst { value: 0 })
                } else {
                    Arc::new(CostExpr::CostConst { value: 1 })
                }
            }
            CostExpr::CostAdd {
                left: l, right: r, ..
            } => {
                let nl = normalize_asymptotic(l.clone());
                let nr = normalize_asymptotic(r.clone());
                if (nl.clone() == nr.clone()) {
                    nl.clone()
                } else {
                    match (*nl.clone()).clone() {
                        CostExpr::CostConst { value: 0, .. } => nr.clone(),
                        CostExpr::CostConst { value: _, .. } => match (*nr.clone()).clone() {
                            CostExpr::CostConst { value: 0, .. } => nl.clone(),
                            CostExpr::CostConst { value: _, .. } => {
                                Arc::new(CostExpr::CostConst { value: 1 })
                            }
                            _ => nr.clone(),
                        },
                        _ => match (*nr.clone()).clone() {
                            CostExpr::CostConst { value: 0, .. } => nl.clone(),
                            CostExpr::CostConst { value: _, .. } => nl.clone(),
                            _ => Arc::new(CostExpr::CostAdd {
                                left: nl.clone(),
                                right: nr.clone(),
                            }),
                        },
                    }
                }
            }
            CostExpr::CostMax {
                left: l, right: r, ..
            } => {
                let nl = normalize_asymptotic(l.clone());
                let nr = normalize_asymptotic(r.clone());
                if (nl.clone() == nr.clone()) {
                    nl.clone()
                } else {
                    match (*nl.clone()).clone() {
                        CostExpr::CostConst { value: 0, .. } => nr.clone(),
                        CostExpr::CostConst { value: _, .. } => match (*nr.clone()).clone() {
                            CostExpr::CostConst { value: 0, .. } => nl.clone(),
                            CostExpr::CostConst { value: _, .. } => {
                                Arc::new(CostExpr::CostConst { value: 1 })
                            }
                            _ => nr.clone(),
                        },
                        _ => match (*nr.clone()).clone() {
                            CostExpr::CostConst { value: 0, .. } => nl.clone(),
                            CostExpr::CostConst { value: _, .. } => nl.clone(),
                            _ => Arc::new(CostExpr::CostMax {
                                left: nl.clone(),
                                right: nr.clone(),
                            }),
                        },
                    }
                }
            }
            CostExpr::CostMul {
                left: l, right: r, ..
            } => {
                let nl = normalize_asymptotic(l.clone());
                let nr = normalize_asymptotic(r.clone());
                match (*nl.clone()).clone() {
                    CostExpr::CostConst { value: 0, .. } => {
                        Arc::new(CostExpr::CostConst { value: 0 })
                    }
                    CostExpr::CostConst { value: _, .. } => nr.clone(),
                    _ => match (*nr.clone()).clone() {
                        CostExpr::CostConst { value: 0, .. } => {
                            Arc::new(CostExpr::CostConst { value: 0 })
                        }
                        CostExpr::CostConst { value: _, .. } => nl.clone(),
                        _ => Arc::new(CostExpr::CostMul {
                            left: nl.clone(),
                            right: nr.clone(),
                        }),
                    },
                }
            }
            CostExpr::CostSum {
                binder: b,
                upper: u,
                body: bd,
                ..
            } => {
                let nbd = normalize_asymptotic(bd.clone());
                match (*nbd.clone()).clone() {
                    CostExpr::CostConst { value: 0, .. } => {
                        Arc::new(CostExpr::CostConst { value: 0 })
                    }
                    _ => match (*u.clone()).clone() {
                        SizeExpr::SizeConst { value: _, .. } => nbd.clone(),
                        _ => Arc::new(CostExpr::CostSum {
                            binder: b.clone(),
                            upper: u.clone(),
                            body: nbd.clone(),
                        }),
                    },
                }
            }
            CostExpr::CostLog {
                base: b,
                argument: a,
                ..
            } => Arc::new(CostExpr::CostLog {
                base: b.clone(),
                argument: a.clone(),
            }),
            CostExpr::CostExtern { name: _, .. } => expr.clone(),
            CostExpr::CostUnknown { reason: _, .. } => expr.clone(),
        }
    })
}

pub fn format_cost_class(expr: Arc<CostExpr>) -> String {
    match (*expr.clone()).clone() {
        CostExpr::CostConst { value: _, .. } => "O(1)".to_string(),
        CostExpr::CostExtern { name: n, .. } => v1_rt::concat(
            v1_rt::concat("O(extern(".to_string(), n.clone()),
            "))".to_string(),
        ),
        CostExpr::CostUnknown { reason: _, .. } => "O(?)".to_string(),
        CostExpr::CostSum {
            upper: u, body: bd, ..
        } => match (*bd.clone()).clone() {
            CostExpr::CostConst { value: _, .. } => v1_rt::concat(
                v1_rt::concat("O(".to_string(), format_size(u.clone())),
                ")".to_string(),
            ),
            _ => v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat("O(".to_string(), format_size(u.clone())),
                        " * ".to_string(),
                    ),
                    format_cost_inner(bd.clone()),
                ),
                ")".to_string(),
            ),
        },
        CostExpr::CostAdd {
            left: l, right: r, ..
        } => v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat("O(".to_string(), format_cost_inner(l.clone())),
                    " + ".to_string(),
                ),
                format_cost_inner(r.clone()),
            ),
            ")".to_string(),
        ),
        CostExpr::CostMul {
            left: l, right: r, ..
        } => v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat("O(".to_string(), parenthesize_additive_cost(l.clone())),
                    " * ".to_string(),
                ),
                parenthesize_additive_cost(r.clone()),
            ),
            ")".to_string(),
        ),
        CostExpr::CostMax {
            left: l, right: r, ..
        } => v1_rt::concat(
            v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat("O(max(".to_string(), format_cost_inner(l.clone())),
                    ", ".to_string(),
                ),
                format_cost_inner(r.clone()),
            ),
            "))".to_string(),
        ),
        CostExpr::CostLog { argument: a, .. } => v1_rt::concat(
            v1_rt::concat("O(log ".to_string(), format_size(a.clone())),
            ")".to_string(),
        ),
    }
}

pub fn format_cost_inner(expr: Arc<CostExpr>) -> String {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*expr.clone()).clone() {
            CostExpr::CostConst { value: _, .. } => "1".to_string(),
            CostExpr::CostSum {
                upper: u, body: bd, ..
            } => match (*bd.clone()).clone() {
                CostExpr::CostConst { value: _, .. } => format_size(u.clone()),
                _ => v1_rt::concat(
                    v1_rt::concat(format_size(u.clone()), " * ".to_string()),
                    format_cost_inner(bd.clone()),
                ),
            },
            CostExpr::CostAdd {
                left: l, right: r, ..
            } => v1_rt::concat(
                v1_rt::concat(format_cost_inner(l.clone()), " + ".to_string()),
                format_cost_inner(r.clone()),
            ),
            CostExpr::CostMul {
                left: l, right: r, ..
            } => {
                let left_str = match (*l.clone()).clone() {
                    CostExpr::CostAdd { .. } => v1_rt::concat(
                        v1_rt::concat("(".to_string(), format_cost_inner(l.clone())),
                        ")".to_string(),
                    ),
                    _ => format_cost_inner(l.clone()),
                };
                let right_str = match (*r.clone()).clone() {
                    CostExpr::CostAdd { .. } => v1_rt::concat(
                        v1_rt::concat("(".to_string(), format_cost_inner(r.clone())),
                        ")".to_string(),
                    ),
                    _ => format_cost_inner(r.clone()),
                };
                v1_rt::concat(
                    v1_rt::concat(left_str.clone(), " * ".to_string()),
                    right_str.clone(),
                )
            }
            CostExpr::CostMax {
                left: l, right: r, ..
            } => v1_rt::concat(
                v1_rt::concat(
                    v1_rt::concat(
                        v1_rt::concat("max(".to_string(), format_cost_inner(l.clone())),
                        ", ".to_string(),
                    ),
                    format_cost_inner(r.clone()),
                ),
                ")".to_string(),
            ),
            CostExpr::CostLog { argument: a, .. } => {
                v1_rt::concat("log ".to_string(), format_size(a.clone()))
            }
            CostExpr::CostExtern { name: n, .. } => v1_rt::concat(
                v1_rt::concat("extern(".to_string(), n.clone()),
                ")".to_string(),
            ),
            CostExpr::CostUnknown { reason: _, .. } => "?".to_string(),
        }
    })
}

pub fn parenthesize_additive_cost(expr: Arc<CostExpr>) -> String {
    match (*expr.clone()).clone() {
        CostExpr::CostAdd { .. } => v1_rt::concat(
            v1_rt::concat("(".to_string(), format_cost_inner(expr.clone())),
            ")".to_string(),
        ),
        _ => format_cost_inner(expr.clone()),
    }
}

pub fn short_var_name(index: i64) -> String {
    if (index.clone() == 0) {
        "n".to_string()
    } else {
        if (index.clone() == 1) {
            "m".to_string()
        } else {
            if (index.clone() == 2) {
                "p".to_string()
            } else {
                if (index.clone() == 3) {
                    "q".to_string()
                } else {
                    if (index.clone() == 4) {
                        "r".to_string()
                    } else {
                        if (index.clone() == 5) {
                            "s".to_string()
                        } else {
                            if (index.clone() == 6) {
                                "t".to_string()
                            } else {
                                if (index.clone() == 7) {
                                    "u".to_string()
                                } else {
                                    if (index.clone() == 8) {
                                        "v".to_string()
                                    } else {
                                        if (index.clone() == 9) {
                                            "w".to_string()
                                        } else {
                                            v1_rt::concat(
                                                "x".to_string(),
                                                (index.clone()).to_string(),
                                            )
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct Legend {
    pub substitution: Arc<HashMap<String, String>>,
    pub suffix: String,
}

pub fn build_legend(size_names: Arc<Vec<String>>) -> Arc<Legend> {
    {
        let unique = deduplicate(size_names.clone());
        if ((unique.clone().len() as i64) == 0) {
            Arc::new(Legend {
                substitution: v1_rt::rc_empty_map::<String, String>(),
                suffix: "".to_string(),
            })
        } else {
            if ((unique.clone().len() as i64) == 1) {
                match unique.clone().first().cloned() {
                    Some(name) => Arc::new(Legend {
                        substitution: v1_rt::rc_map_insert(
                            v1_rt::rc_empty_map::<String, String>(),
                            name.clone(),
                            "n".to_string(),
                        ),
                        suffix: "".to_string(),
                    }),
                    None => Arc::new(Legend {
                        substitution: v1_rt::rc_empty_map::<String, String>(),
                        suffix: "".to_string(),
                    }),
                }
            } else {
                {
                    let indexed = unique.clone().iter().cloned().fold(
                        Arc::new(Legend {
                            substitution: v1_rt::rc_empty_map::<String, String>(),
                            suffix: "".to_string(),
                        }),
                        |acc: Arc<Legend>, name: String| {
                            let idx =
                                (Arc::new(v1_rt::map_keys(&acc.substitution.clone())).len() as i64);
                            let short = short_var_name(idx.clone());
                            Arc::new(Legend {
                                substitution: v1_rt::rc_map_insert(
                                    acc.substitution.clone(),
                                    name.clone(),
                                    short.clone(),
                                ),
                                suffix: if (acc.suffix.clone() == "".to_string()) {
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(" where ".to_string(), short.clone()),
                                            " = ".to_string(),
                                        ),
                                        name.clone(),
                                    )
                                } else {
                                    v1_rt::concat(
                                        v1_rt::concat(
                                            v1_rt::concat(
                                                v1_rt::concat(acc.suffix.clone(), ", ".to_string()),
                                                short.clone(),
                                            ),
                                            " = ".to_string(),
                                        ),
                                        name.clone(),
                                    )
                                },
                            })
                        },
                    );
                    indexed
                }
            }
        }
    }
}

pub fn substitute_size(size: Arc<SizeExpr>, legend: Arc<HashMap<String, String>>) -> Arc<SizeExpr> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*size.clone()).clone() {
            SizeExpr::SizeLen { collection: c, .. } => match v1_rt::map_get(&legend, c.clone()) {
                Some(short) => Arc::new(SizeExpr::SizeVar {
                    name: short.clone(),
                }),
                None => size.clone(),
            },
            SizeExpr::SizeVar { name: n, .. } => match v1_rt::map_get(&legend, n.clone()) {
                Some(short) => Arc::new(SizeExpr::SizeVar {
                    name: short.clone(),
                }),
                None => size.clone(),
            },
            SizeExpr::SizeAdd {
                left: l, right: r, ..
            } => Arc::new(SizeExpr::SizeAdd {
                left: substitute_size(l.clone(), legend.clone()),
                right: substitute_size(r.clone(), legend.clone()),
            }),
            SizeExpr::SizeMax {
                left: l, right: r, ..
            } => Arc::new(SizeExpr::SizeMax {
                left: substitute_size(l.clone(), legend.clone()),
                right: substitute_size(r.clone(), legend.clone()),
            }),
            SizeExpr::SizeConst { value: _, .. } => size.clone(),
        }
    })
}

pub fn substitute_cost(expr: Arc<CostExpr>, legend: Arc<HashMap<String, String>>) -> Arc<CostExpr> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*expr.clone()).clone() {
            CostExpr::CostConst { value: _, .. } => expr.clone(),
            CostExpr::CostAdd {
                left: l, right: r, ..
            } => Arc::new(CostExpr::CostAdd {
                left: substitute_cost(l.clone(), legend.clone()),
                right: substitute_cost(r.clone(), legend.clone()),
            }),
            CostExpr::CostMul {
                left: l, right: r, ..
            } => Arc::new(CostExpr::CostMul {
                left: substitute_cost(l.clone(), legend.clone()),
                right: substitute_cost(r.clone(), legend.clone()),
            }),
            CostExpr::CostMax {
                left: l, right: r, ..
            } => Arc::new(CostExpr::CostMax {
                left: substitute_cost(l.clone(), legend.clone()),
                right: substitute_cost(r.clone(), legend.clone()),
            }),
            CostExpr::CostSum {
                binder: b,
                upper: u,
                body: bd,
                ..
            } => Arc::new(CostExpr::CostSum {
                binder: b.clone(),
                upper: substitute_size(u.clone(), legend.clone()),
                body: substitute_cost(bd.clone(), legend.clone()),
            }),
            CostExpr::CostLog {
                base: b,
                argument: a,
                ..
            } => Arc::new(CostExpr::CostLog {
                base: b.clone(),
                argument: substitute_size(a.clone(), legend.clone()),
            }),
            CostExpr::CostExtern { name: _, .. } => expr.clone(),
            CostExpr::CostUnknown { reason: _, .. } => expr.clone(),
        }
    })
}

pub fn classify_complexity(expr: Arc<CostExpr>) -> String {
    {
        let normalized = normalize_asymptotic(simplify_cost(expr.clone()));
        let size_names = collect_size_vars(normalized.clone());
        let legend = build_legend(size_names.clone());
        let substituted = substitute_cost(normalized.clone(), legend.substitution.clone());
        v1_rt::concat(
            format_cost_class(substituted.clone()),
            legend.suffix.clone(),
        )
    }
}

pub fn collect_size_vars_from_size(size: Arc<SizeExpr>) -> Arc<Vec<String>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*size.clone()).clone() {
            SizeExpr::SizeLen { collection: c, .. } => {
                if (c.clone() == "__expr".to_string()) {
                    Arc::new(vec![])
                } else {
                    Arc::new(vec![c.clone()])
                }
            }
            SizeExpr::SizeVar { name: n, .. } => {
                if (n.clone() == "__k".to_string()) {
                    Arc::new(vec![])
                } else {
                    Arc::new(vec![n.clone()])
                }
            }
            SizeExpr::SizeAdd {
                left: l, right: r, ..
            } => v1_rt::concat(
                collect_size_vars_from_size(l.clone()),
                collect_size_vars_from_size(r.clone()),
            ),
            SizeExpr::SizeMax {
                left: l, right: r, ..
            } => v1_rt::concat(
                collect_size_vars_from_size(l.clone()),
                collect_size_vars_from_size(r.clone()),
            ),
            _ => Arc::new(vec![]),
        }
    })
}

pub fn collect_size_vars(expr: Arc<CostExpr>) -> Arc<Vec<String>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*expr.clone()).clone() {
            CostExpr::CostSum {
                upper: u, body: bd, ..
            } => v1_rt::concat(
                collect_size_vars_from_size(u.clone()),
                collect_size_vars(bd.clone()),
            ),
            CostExpr::CostAdd {
                left: l, right: r, ..
            } => v1_rt::concat(collect_size_vars(l.clone()), collect_size_vars(r.clone())),
            CostExpr::CostMul {
                left: l, right: r, ..
            } => v1_rt::concat(collect_size_vars(l.clone()), collect_size_vars(r.clone())),
            CostExpr::CostMax {
                left: l, right: r, ..
            } => v1_rt::concat(collect_size_vars(l.clone()), collect_size_vars(r.clone())),
            CostExpr::CostLog { argument: a, .. } => collect_size_vars_from_size(a.clone()),
            _ => Arc::new(vec![]),
        }
    })
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct DeduplicateAcc {
    pub seen: Arc<HashMap<String, bool>>,
    pub out: Arc<Vec<String>>,
}

pub fn deduplicate(items: Arc<Vec<String>>) -> Arc<Vec<String>> {
    {
        let result = items.clone().iter().cloned().fold(
            Arc::new(DeduplicateAcc {
                seen: v1_rt::rc_empty_map::<String, bool>(),
                out: Arc::new(vec![]),
            }),
            |acc: Arc<DeduplicateAcc>, item: String| match v1_rt::map_get(
                &acc.seen.clone(),
                item.clone(),
            ) {
                Some(_) => acc.clone(),
                None => Arc::new(DeduplicateAcc {
                    seen: v1_rt::rc_map_insert(acc.seen.clone(), item.clone(), true),
                    out: v1_rt::rc_list_push(acc.out.clone(), item.clone()),
                }),
            },
        );
        result.out.clone()
    }
}

